window.TXB=window.TXB||{};TXB["alab/Joh"]={"1:1":"في البدء كان الكلمة، والكلمة كان عند الله. وكان الكلمة هو الله.","1:2":"هو كان في البدء عند الله.","1:3":"به تكون كل شيء، وبغيره لم يتكون أي شيء مما تكون.","1:4":"فيه كانت الحياة. والحياة هذه كانت نور الناس.","1:5":"والنور يضيء في الظلام، والظلام لم يدرك النور.","1:6":"ظهر إنسان أرسله الله، اسمه يوحنا،","1:7":"جاء يشهد للنور، من أجل أن يؤمن الجميع بواسطته.","1:8":"لم يكن هو النور، بل كان شاهدا للنور،","1:9":"فالنور الحق الذي ينير كل إنسان كان آتيا إلى العالم.","1:10":"كان في العالم، وبه تكون العالم، ولم يعرفه العالم.","1:11":"وقد جاء إلى من كانوا خاصته، ولكن هؤلاء لم يقبلوه.","1:12":"أما الذين قبلوه، أي الذين آمنوا باسمه، فقد منحهم الحق في أن يصيروا أولاد الله،","1:13":"وهم الذين ولدوا ليس من دم، ولا من رغبة جسد، ولا من رغبة بشر، بل من الله.","1:14":"والكلمة صار بشرا، وخيم بيننا، ونحن رأينا مجده، مجد ابن وحيد عند الآب، وهو ممتلىء بالنعمة والحق.","1:15":"شهد له يوحنا فهتف قائلا: «هذا هو الذي قلت عنه: إن الآتي بعدي متقدم علي، لأنه كان قبل أن أوجد».","1:16":"فمن امتلائه أخذنا جميعنا ونلنا نعمة على نعمة،","1:17":"لأن الشريعة أعطيت على يد موسى، أما النعمة والحق فقد تواجدا بيسوع المسيح.","1:18":"ما من أحد رأى الله قط. ولكن الابن الوحيد، الذي في حضن الآب، هو الذي كشف عنه.","1:19":"وهذه شهادة يوحنا حين أرسل اليهود من أورشليم بعض الكهنة واللاويين يسألونه: «من أنت؟»","1:20":"فاعترف ولم ينكر، بل أكد قائلا: «لست أنا المسيح».","1:21":"فسألوه: «ماذا إذن؟ هل أنت إيليا؟» قال: «لست إياه!»؛ «أو أنت النبي؟» فأجاب: «لا!»","1:22":"فقالوا: «فمن أنت، لنحمل الجواب إلى الذين أرسلونا؟ ماذا تقول عن نفسك؟»","1:23":"فقال «أنا صوت مناد في البرية: اجعلوا الطريق مستقيمة أمام الرب، كما قال النبي إشعياء».","1:24":"وكان هؤلاء مرسلين من قبل الفريسيين،","1:25":"فعادوا يسألونه: «إن لم تكن أنت المسيح، ولا إيليا، ولا النبي، فلماذا تعمد إذن؟»","1:26":"أجاب: «أنا أعمد بالماء! ولكن بينكم من لا تعرفونه،","1:27":"وهو الآتي بعدي، وأنا لا أستحق أن أحل رباط حذائه».","1:28":"هذا جرى في بيت عنيا، في ما وراء نهر الأردن، حيث كان يوحنا يعمد.","1:29":"وفي اليوم التالي رأى يوحنا يسوع آتيا نحوه، فهتف قائلا: «هذا هو حمل الله الذي يزيل خطيئة العالم.","1:30":"هذا هو الذي قلت عنه إن الرجل الآتي بعدي متقدم علي لأنه كان قبل أن أوجد.","1:31":"ولم أكن أعرفه ولكني جئت أعمد بالماء لكي يعلن لإسرائيل».","1:32":"ثم شهد يوحنا فقال: «رأيت الروح ينزل من السماء بهيئة حمامة ويستقر عليه.","1:33":"ولم أكن أعرفه، ولكن الذي أرسلني لأعمد بالماء هو قال لي: الذي ترى الروح ينزل ويستقر عليه هو الذي سيعمد بالروح القدس.","1:34":"فإذ شاهدت هذا، أشهد أنه هو ابن الله».","1:35":"وفي اليوم التالي كان يوحنا واقفا هناك أيضا ومعه اثنان من تلاميذه،","1:36":"فنظر إلى يسوع وهو سائر فقال: «هذا هو حمل الله».","1:37":"فلما سمع التلميذان كلامه تبعا يسوع.","1:38":"والتفت يسوع فرآهما يتبعانه، فسألهما: «ماذا تريدان؟» فقالا: «رابي، أي يامعلم، أين تقيم؟»","1:39":"أجابهما: «تعاليا وانظرا». فرافقاه ورأيا محل إقامته، وأقاما معه ذلك اليوم؛ وكانت الساعة نحو الرابعة بعد الظهر.","1:40":"وكان أندراوس أخو سمعان بطرس أحد هذين اللذين تبعا يسوع، بعدما سمعا كلام يوحنا،","1:41":"فما إن وجد أخاه سمعان، حتى قال له: «وجدنا المسيا» أي المسيح.","1:42":"واقتاده إلى يسوع. فنظر يسوع مليا إلى سمعان وقال: «أنت سمعان بن يونا، ولكني سأدعوك: صفا» أي صخرا.","1:43":"وفي اليوم التالي نوى يسوع أن يذهب إلى منطقة الجليل، فوجد فيلبس، فقال له: «اتبعني!»","1:44":"وكان فيلبس من بيت صيدا، بلدة أندراوس وبطرس.","1:45":"ثم وجد فيلبس نثنائيل، فقال له: «وجدنا الذي كتب عنه موسى في الشريعة، والأنبياء في كتبهم وهو يسوع ابن يوسف من الناصرة».","1:46":"فقال نثنائيل: «وهل يطلع من الناصرة شيء صالح؟» أجابه فيلبس: «تعال وانظر!»","1:47":"ورأى يسوع نثنائيل قادما نحوه فقال عنه: «هذا إسرائيلي أصيل لا شك فيه!»","1:48":"فسأله نثنائيل: «ومن أين تعرفني؟» فأجابه يسوع: «رأيتك تحت التينة قبل أن يدعوك فيلبس».","1:49":"فهتف نثنائيل قائلا: «يامعلم، أنت ابن الله! أنت ملك إسرائيل!»","1:50":"فقال له يسوع: «هل آمنت لأني قلت لك إني رأيتك تحت التينة؟ سوف ترى أعظم من هذا!»","1:51":"ثم قال له: «الحق الحق أقول لكم: إنكم سترون السماء مفتوحة، وملائكة الله يصعدون وينزلون على ابن الإنسان!»","2:1":"وفي اليوم الثالث كان عرس في قانا بمنطقة الجليل، وكانت هناك أم يسوع.","2:2":"ودعي إلى العرس أيضا يسوع وتلاميذه.","2:3":"فلما نفدت الخمر، قالت أم يسوع له: «لم يبق عندهم خمر!»","2:4":"فأجابها: «ما شأنك بي ياامرأة؟ ساعتي لم تأت بعد!»","2:5":"فقالت أمه للخدم: «افعلوا كل ما يأمركم به».","2:6":"وكانت هناك ستة أجران حجرية، يستعمل اليهود ماءها للتطهر، يسع الواحد منها ما بين مكيالين أو ثلاثة (أي ما بين ثمانين إلى مئة وعشرين لترا).","2:7":"فقال يسوع للخدم: «املأوا الأجران ماء». فملأوها حتى كادت تفيض.","2:8":"ثم قال لهم: «والآن اغرفوا منها وقدموا إلى رئيس الوليمة!» ففعلوا.","2:9":"ولما ذاق رئيس الوليمة الماء الذي كان قد تحول إلى خمر، ولم يكن يعرف مصدره، أما الخدم الذين قدموه فكانوا يعرفون، استدعى العريس،","2:10":"وقال له: «الناس جميعا يقدمون الخمر الجيدة أولا، وبعد أن يسكر الضيوف يقدمون لهم ما كان دونها جودة. أما أنت فقد أبقيت الخمر الجيدة حتى الآن!»","2:11":"هذه المعجزة هي الآية الأولى التي أجراها يسوع في قانا بالجليل، وأظهر مجده، فآمن به تلاميذه.","2:12":"وبعد هذا، نزل يسوع وأمه وإخوته وتلاميذه إلى مدينة كفرناحوم، حيث أقاموا بضعة أيام.","2:13":"وإذ اقترب عيد الفصح اليهودي، صعد يسوع إلى أورشليم،","2:14":"فوجد في الهيكل باعة البقر والغنم والحمام، والصيارفة جالسين إلى موائدهم،","2:15":"فجدل سوطا من حبال، وطردهم جميعا من الهيكل، مع الغنم والبقر، وبعثر نقود الصيارفة وقلب مناضدهم،","2:16":"وقال لبائعي الحمام: «أخرجوا هذه من هنا. لا تجعلوا بيت أبي بيتا للتجارة!»","2:17":"فتذكر تلاميذه أنه جاء في الكتاب: «الغيرة على بيتك تلتهمني».","2:18":"فتصدى اليهود ليسوع وقالوا له: «هات آية تثبت سلطتك لفعل ما فعلت!»","2:19":"أجابهم يسوع: «اهدموا هذا الهيكل، وفي ثلاثة أيام أقيمه».","2:20":"فقال له اليهود: «اقتضى بناء هذا الهيكل ستة وأربعين عاما، فهل تقيمه أنت في ثلاثة أيام؟»","2:21":"ولكنه كان يشير إلى هيكل جسده.","2:22":"فلما قام من بين الأموات فيما بعد تذكر تلاميذه قوله هذا، فآمنوا بالكتاب وبالكلام الذي قاله يسوع.","2:23":"وبينما كان في أورشليم في عيد الفصح، آمن باسمه كثيرون إذ شهدوا الآيات التي أجراها.","2:24":"ولكنه هو لم يأتمنهم على نفسه، لأنه كان يعرف الجميع","2:25":"ولم يكن بحاجة إلى من يشهد له عن الإنسان، لأنه يعرف دخيلة الإنسان.","3:1":"غير أن إنسانا من الفريسيين، اسمه نيقوديموس، وهو عضو في المجلس اليهودي،","3:2":"جاء إلى يسوع ليلا وقال له: «يامعلم، نعلم أنك جئت من الله معلما، لأنه لا يقدر أحد أن يعمل ما تعمل من آيات إلا إذا كان الله معه».","3:3":"فأجابه يسوع: «الحق الحق أقول لك: لا أحد يمكنه أن يرى ملكوت الله إلا إذا ولد من جديد».","3:4":"فسأله نيقوديموس: «كيف يمكن الإنسان أن يولد وهو كبير السن؟ ألعله يستطيع أن يدخل بطن أمه ثانية ثم يولد؟»","3:5":"أجابه يسوع: «الحق الحق أقول لك: لا يمكن أن يدخل أحد ملكوت الله إلا إذا ولد من الماء والروح.","3:6":"فالمولود من الجسد هو جسد، والمولود من الروح هو روح.","3:7":"فلا تتعجب إذا قلت لك إنكم بحاجة إلى الولادة من جديد.","3:8":"الريح تهب حيث تشاء وتسمع صفيرها، ولكنك لا تعلم من أين تأتي ولا إلى أين تذهب. هكذا كل من ولد من الروح».","3:9":"فعاد نيقوديموس يسأل: «كيف يمكن أن يتم هذا؟»","3:10":"أجابه يسوع: «أنت معلم إسرائيل ولا تعلم هذا!","3:11":"الحق الحق أقول لك: إننا نتكلم بما نعلم ونشهد بما رأينا، ومع ذلك لا تقبلون شهادتنا.","3:12":"إن كنت حدثتكم بأمور الأرض ولم تؤمنوا، فكيف تؤمنون إن حدثتكم بأمور السماء؟","3:13":"وما صعد أحد إلى السماء إلا الذي نزل من السماء، وهو ابن الإنسان الذي هو في السماء.","3:14":"وكما علق موسى الحية في البرية، فكذلك لا بد من أن يعلق ابن الإنسان،","3:15":"لتكون الحياة الأبدية لكل من يؤمن به.","3:16":"لأنه هكذا أحب الله العالم حتى بذل ابنه الوحيد، لكي لا يهلك كل من يؤمن به، بل تكون له الحياة الأبدية.","3:17":"فإن الله لم يرسل ابنه إلى العالم ليدين العالم، بل ليخلص العالم به،","3:18":"فالذي يؤمن به لا يدان، أما الذي لا يؤمن به فقد صدر عليه حكم الدينونة، لأنه لم يؤمن باسم ابن الله الوحيد.","3:19":"وهذا هو الحكم: إن النور قد جاء إلى العالم، ولكن الناس أحبوا الظلمة أكثر من النور، لأن أعمالهم كانت شريرة.","3:20":"فكل من يعمل الشر يبغض النور، ولا يأتي إليه مخافة أن تفضح أعماله.","3:21":"وأما الذي يسلك في الحق فيأتي إلى النور لتظهر أعماله ويتبين أنها عملت بقوة الله».","3:22":"وذهب يسوع وتلاميذه بعد ذلك إلى بلاد اليهودية وأقام فيها معهم، وأخذ يعمد.","3:23":"وكان يوحنا أيضا يعمد في عين نون بالقرب من ساليم، لأن المياه هناك كانت كثيرة فكان الناس يأتون ويتعمدون.","3:24":"فإن يوحنا لم يكن قد ألقي بعد في السجن.","3:25":"وحدث جدال بين تلاميذ يوحنا وأحد اليهود في شأن التطهر.","3:26":"فذهبوا إلى يوحنا وقالوا له: «يامعلم، الرجل الذي رأيناه معك في ما وراء نهر الأردن، والذي شهدت له، هو أيضا يعمد، والجميع يتحولون إليه!»","3:27":"فأجاب يوحنا: «لا يقدر أحد أن ينال شيئا إلا إذا أعطي له من السماء!","3:28":"أنتم تشهدون أني قلت: لست المسيح، بل أنا رسول يمهد له الطريق.","3:29":"ومن له العروس، يكون هو العريس! أما صديق العريس، الذي يقف قربه ويسمعه، فيبتهج لفرحه بصوت العريس. وها إن فرحي هذا قد تم.","3:30":"فلابد أن يزيد هو وأنقص أنا»","3:31":"إنه هو الآتي من السماء، ولذلك فهو متقدم على الجميع. أما من كان من الأرض، فإنه أرضي ويتكلم كلاما أرضيا. الآتي من السماء متقدم على الجميع،","3:32":"وهو يشهد بما سمع ورأى، ولا أحد يقبل شهادته!","3:33":"على أن الذي يقبل شهادته، يصادق على أن الله حق،","3:34":"لأن الذي أرسله الله يتكلم بكلام الله فإن الله يعطي الروح ليس بالمكيال.","3:35":"فالآب يحب الابن، وقد جعل في يده كل شيء.","3:36":"من يؤمن بالابن، فله الحياة الأبدية. ومن يرفض أن يؤمن بالابن، فلن يرى الحياة. بل يستقر عليه غضب الله».","4:1":"ولما عرف الرب أن الفريسيين سمعوا أنه يتخذ تلاميذ ويعمد أكثر من يوحنا،","4:2":"مع أن يسوع نفسه لم يكن يعمد بل تلاميذه،","4:3":"ترك منطقة اليهودية ورجع إلى منطقة الجليل.","4:4":"وكان لابد له أن يمر بمنطقة السامرة،","4:5":"فوصل إلى بلدة فيها، تدعى سوخار، قريبة من الأرض التي وهبها يعقوب لابنه يوسف،","4:6":"حيث بئر يعقوب. ولما كان يسوع قد تعب من السفر، جلس على حافة البئر، وكانت الساعة حوالي السادسة.","4:7":"وجاءت امرأة سامرية إلى البئر لتأخذ ماء، فقال لها يسوع: «اسقيني!»","4:8":"فإن تلاميذه كانوا قد ذهبوا إلى البلدة ليشتروا طعاما.","4:9":"فقالت له المرأة السامرية: «أنت يهودي وأنا سامرية، فكيف تطلب مني أن أسقيك؟» فإن اليهود كانوا لا يتعاملون مع أهل السامرة.","4:10":"فأجابها يسوع: «لو كنت تعرفين عطية الله، ومن هو الذي يقول لك: اسقيني، لطلبت أنت منه فأعطاك ماء حيا!»","4:11":"فقالت المرأة: «ولكن ياسيد، ليس معك دلو، والبئر عميقة. فمن أين لك الماء الحي؟","4:12":"هل أنت أعظم من أبينا يعقوب الذي أورثنا هذه البئر، وقد شرب منها هو وبنوه ومواشيه؟»","4:13":"فقال لها يسوع: «كل من يشرب من هذا الماء يعود فيعطش.","4:14":"ولكن الذي يشرب من الماء الذي أعطيه أنا، لن يعطش بعد ذلك أبدا، بل إن ما أعطيه من ماء يصبح في داخله نبعا يفيض فيعطي حياة أبدية».","4:15":"فقالت له المرأة: «ياسيد، أعطني هذا الماء فلا أعطش ولا أعود إلى هنا لآخذ ماء».","4:16":"فقال لها: «اذهبي وادعي زوجك، وارجعي إلى هنا».","4:17":"فأجابت: «ليس لي زوج!» فقال: «صدقت إذ قلت: ليس لي زوج","4:18":"فقد كان لك خمسة أزواج، والذي تعيشين معه الآن ليس زوجك. هذا قلته بالصدق!»","4:19":"فقالت له المرأة: «ياسيد، أرى أنك نبي.","4:20":"آباؤنا عبدوا الله في هذا الجبل، وأنتم اليهود تصرون على أن أورشليم يجب أن تكون المركز الوحيد للعبادة».","4:21":"فأجابها يسوع: «صدقيني ياامرأة، ستأتي الساعة التي فيها تعبدون الآب لا في هذا الجبل ولا في أورشليم.","4:22":"أنتم تعبدون ما تجهلون، ونحن نعبد ما نعلم، لأن الخلاص هو من عند اليهود.","4:23":"فستأتي ساعة، لا بل هي الآن، حين يعبد العابدون الصادقون الآب بالروح وبالحق. لأن الآب يبتغي مثل هؤلاء العابدين.","4:24":"الله روح، فلذلك لابد لعابديه من أن يعبدوه بالروح وبالحق».","4:25":"فقالت له المرأة: «إني أعلم أن المسيا، الذي يدعى المسيح، سيأتي، ومتى جاء فهو يعلن لنا كل شيء».","4:26":"فأجابها: «إني أنا هو؛ هذا الذي يكلمك!»","4:27":"وعند ذلك وصل التلاميذ، ودهشوا لما رأوه يحادث امرأة. ومع ذلك لم يقل له أحد منهم: «ماذا تريد منها؟» أو «لماذا تحادثها؟»","4:28":"فتركت المرأة جرتها وعادت إلى البلدة، وأخذت تقول للناس:","4:29":"«تعالوا انظروا إنسانا كشف لي كل ما فعلت! فلعله هو المسيح؟»","4:30":"فخرج أهل سوخار وأقبلوا إليه.","4:31":"وفي أثناء ذلك كان التلاميذ يقولون له بإلحاح: «يامعلم، كل»","4:32":"فأجابهم: «عندي طعام آكله لا تعرفونه أنتم».","4:33":"فأخذ التلاميذ يتساءلون: «هل جاءه أحد بما يأكله؟»","4:34":"فقال لهم يسوع: «طعامي هو أن أعمل مشيئة الذي أرسلني وأن أنجز عمله.","4:35":"أما تقولون: بعد أربعة أشهر يأتي الحصاد! ولكني أقول لكم: انظروا مليا إلى الحقول، فهي قد نضجت وحان حصادها.","4:36":"والحاصد يأخذ أجرته، ويجمع الثمر للحياة الأبدية، فيفرح الزارع والحاصد معا،","4:37":"حتى يصدق القول: واحد يزرع، وآخر يحصد.","4:38":"إني أرسلتكم لتحصدوا ما لم تتعبوا فيه، فغيركم تعبوا، وأنتم تجنون ثمر أتعابهم».","4:39":"فآمن به كثيرون من السامريين أهل تلك البلدة بسبب كلام المرأة التي كانت تشهد قائلة: «كشف لي كل ما فعلت».","4:40":"وعندما قابلوه عند البئر دعوه أن يقيم عندهم، فأقام هنالك يومين،","4:41":"وتكاثر جدا عدد الذين آمنوا به بسبب كلامه،","4:42":"وقالوا للمرأة: «إننا لا نؤمن بعد الآن بسبب كلامك، بل نؤمن لأننا سمعناه بأنفسنا، وعرفنا أنه مخلص العالم حقا!»","4:43":"وبعد قضاء اليومين في سوخار، غادرها يسوع وسافر إلى منطقة الجليل،","4:44":"وهو نفسه كان قد شهد قائلا: «لا كرامة لنبي في وطنه!»","4:45":"فلما وصل إلى الجليل رحب به أهلها، وكانوا قد رأوا كل ما فعله في أورشليم في أثناء عيد الفصح، إذ ذهبوا هم أيضا إلى العيد.","4:46":"ووصل يسوع إلى قانا بالجليل، حيث كان قد حول الماء إلى خمر. وكان في كفرناحوم رجل من حاشية الملك، له ابن مريض.","4:47":"فلما سمع أن يسوع ترك اليهودية وجاء إلى الجليل، ذهب إليه وطلب منه أن ينزل معه إلى كفرناحوم ليشفي ابنه المشرف على الموت.","4:48":"فقال يسوع: «لا تؤمنون إلا إذا رأيتم الآيات والعجائب!»","4:49":"فتوسل إليه الرجل وقال: «ياسيد، انزل معي قبل أن يموت ابني!»","4:50":"أجابه يسوع: «اذهب! إن ابنك حي!» فآمن الرجل بكلمة يسوع التي قالها له، وانصرف.","4:51":"وبينما كان نازلا في الطريق لاقاه بعض عبيده وبشروه بأن ابنه حي،","4:52":"فسألهم في أية ساعة تعافى، أجابوه: «في الساعة السابعة مساء البارحة، ولت عنه الحمى».","4:53":"فعلم الأب أنها الساعة التي قال له يسوع فيها: «إن ابنك حي». فآمن هو وأهل بيته جميعا.","4:54":"هذه المعجزة هي الآية الثانية التي أجراها يسوع بعد خروجه من اليهودية إلى الجليل.","5:1":"وبعد ذلك صعد يسوع إلى أورشليم في أحد الأعياد اليهودية،","5:2":"وكان بالقرب من باب الغنم في أورشليم بركة اسمها بالعبرية بيت حسدا، حولها خمس قاعات.","5:3":"يرقد فيها جمع كبير من المرضى من عميان وعرج ومشلولين، ينتظرون أن تتحرك مياه البركة،","5:4":"لأن ملاكا كان يأتي من حين لآخر إلى البركة ويحرك ماءها، فكان الذي ينزل أولا يشفى، مهما كان مرضه.","5:5":"وكان عند البركة مريض منذ ثمان وثلاثين سنة،","5:6":"رآه يسوع راقدا هناك فعرف أن مدة طويلة انقضت وهو على تلك الحال، فسأله: «أتريد أن تشفى؟»","5:7":"فأجابه المريض: «ياسيد، ليس لي إنسان يلقيني في البركة متى تحرك الماء. وكم من مرة حاولت النزول، فكان غيري ينزل قبلي دائما».","5:8":"فقال له يسوع: «قم احمل فراشك وامش».","5:9":"وفي الحال شفي الرجل وحمل فراشه ومشى. وكان ذلك يوم سبت.","5:10":"فقال اليهود للرجل الذي شفي: «اليوم سبت. لا يحل لك أن تحمل فراشك!»","5:11":"فأجابهم: «الذي أعاد إلي الصحة هو قال لي: احمل فراشك وامش».","5:12":"فسألوه: «ومن هو الذي قال لك: احمل فراشك وامش؟»","5:13":"ولكن المريض الذي شفي لم يكن يعرف من هو، لأن يسوع كان قد انسحب، إذ كان في المكان جمع.","5:14":"وبعد ذلك وجده يسوع في الهيكل، فقال له: «ها أنت قد عدت صحيحا فلا ترجع إلى الخطيئة لئلا يصيبك ما هو أسوأ!»","5:15":"فلما عرف الرجل أن يسوع هو الذي شفاه، أسرع يخبر اليهود بذلك.","5:16":"فأخذ اليهود يضايقون يسوع لأنه كان يعمل هذه الأعمال يوم السبت.","5:17":"ولكن يسوع قال لهم: «ما زال أبي يعمل إلى الآن. وأنا أيضا أعمل!»","5:18":"لهذا ازداد سعي اليهود إلى قتله، ليس فقط لأنه خالف سنة السبت، بل أيضا لأنه قال إن الله أبوه، مساويا نفسه بالله.","5:19":"فقال لهم يسوع: «الحق الحق أقول لكم إن الابن لا يقدر أن يفعل شيئا من تلقاء نفسه، بل يفعل ما يرى الآب يفعله. فكل ما يعمله الآب، يعمله الابن كذلك،","5:20":"لأن الآب يحب الابن، ويريه جميع ما يفعله، وسيريه أيضا أعمالا أعظم من هذا العمل، فتدهشون.","5:21":"فكما يقيم الآب الموتى ويحييهم، كذلك يحيي الابن من يشاء.","5:22":"والآب لا يحاكم أحدا، بل أعطى الابن سلطة القضاء كلها،","5:23":"ليكرم الجميع الابن كما يكرمون الآب. ومن لا يكرم الابن لا يكرم الآب الذي أرسله.","5:24":"الحق الحق أقول لكم إن من يسمع كلامي ويؤمن بالذي أرسلني تكون له الحياة الأبدية، ولا يحاكم في اليوم الأخير، لأنه قد انتقل من الموت إلى الحياة.","5:25":"الحق الحق أقول لكم: إن الساعة التي يسمع فيها الأموات صوت ابن الله ستأتي بل هي الآن والذين يسمعونه يحيون.","5:26":"لأنه كما أن للآب حياة في ذاته، فقد أعطى الابن أيضا أن تكون له حياة في ذاته،","5:27":"وأعطاه سلطة أن يدين، لأنه ابن الإنسان.","5:28":"لا تتعجبوا من هذا: فسوف تأتي ساعة يسمع فيها جميع من في القبور صوته،","5:29":"فيخرجون منها: فالذين عملوا الصالحات يخرجون في القيامة المؤدية إلى الحياة، وأما الذين عملوا السيئات ففي القيامة المؤدية إلى الدينونة.","5:30":"وأنا لا يمكن أن أفعل شيئا من تلقاء ذاتي، بل أحكم حسبما أسمع، وحكمي عادل، لأني لا أسعى لتحقيق إرادتي بل إرادة الذي أرسلني.","5:31":"لو كنت أشهد لنفسي، لكانت شهادتي غير صادقة،","5:32":"ولكن غيري يؤدي الشهادة لي، وأنا أعلم أن شهادته لي هي حق.","5:33":"وقد بعثتم رسلا إلى يوحنا فشهد للحق.","5:34":"وأنا أقول هذا لا لأني أعتمد على شهادة إنسان، بل من أجل خلاصكم،","5:35":"فقد كان يوحنا مصباحا متوهجا مضيئا، وشئتم أن تستمتعوا بنوره فترة من الزمن.","5:36":"ولكن لي شهادة أعظم من شهادة يوحنا، وهي شهادة الأعمال التي كلفني الآب أن أنجزها والتي أعملها، فهي تشهد لي مبينة أن الآب أرسلني،","5:37":"والآب الذي أرسلني هو نفسه أيضا يشهد لي. وأنتم لم تسمعوا صوته قط، ولا رأيتم هيئته،","5:38":"ولا ثبتت كلمته في قلوبكم، بدليل أنكم لا تصدقون الذي أرسله.","5:39":"أنتم تدرسون الكتب لأنكم تعتقدون أنها ستهديكم إلى الحياة الأبدية. هذه الكتب تشهد لي،","5:40":"ولكنكم ترفضون أن تأتوا إلي لتكون لكم الحياة.","5:41":"لست أقبل مجدا من عند الناس.","5:42":"ولكني أعرفكم، وأعرف أن محبة الله ليست في نفوسكم.","5:43":"فقد جئت باسم أبي ولم تقبلوني، ولكنكم ترحبون بمن يجيء باسم نفسه.","5:44":"من أين لكم أن تؤمنوا بي وأنتم تقبلون المجد بعضكم من بعض، دون أن تسعوا في طلب المجد الذي لا يمنحه إلا الله!","5:45":"لا تظنوا أني أشكوكم إلى الآب، فإن هنالك من يشكوكم، وهو موسى الذي علقتم عليه رجاءكم.","5:46":"فلو كنتم صدقتم موسى، لكنتم صدقتموني، لأنه هو كتب عني.","5:47":"وإذا كنتم لا تصدقون ما كتبه موسى، فكيف تصدقون كلامي؟»","6:1":"بعد ذلك عبر يسوع بحيرة الجليل، أي بحيرة طبرية، إلى الضفة المقابلة،","6:2":"وتبعه جمع كبير بعدما رأوا آيات شفائه للمرضى.","6:3":"وصعد يسوع وتلاميذه إلى الجبل وجلسوا.","6:4":"وكان عيد الفصح اليهودي قد اقترب.","6:5":"وإذ تطلع يسوع ورأى جمعا كبيرا قادما نحوه، قال لفيلبس: «من أين نشتري خبزا لنطعم هؤلاء كلهم؟»","6:6":"وقد قال هذا ليمتحنه، لأن يسوع كان يعرف ما سيفعله.","6:7":"فأجابه فيلبس: «حتى لو اشترينا خبزا بمئتي دينار، لما كان يكفي ليحصل الواحد منهم على قطعة صغيرة!»","6:8":"فقال له أندراوس، أخو سمعان بطرس، وهو أحد التلاميذ:","6:9":"«هنا ولد معه خمسة أرغفة شعير وسمكتان صغيرتان. ولكن ما هذه لمثل هذا الجمع الكبير؟»","6:10":"فقال يسوع: «أجلسوهم!» وكان هناك عشب كثير. فجلس الرجال، وكان عددهم نحو خمسة آلاف.","6:11":"فأخذ يسوع الأرغفة وشكر، ثم وزع منها على الجالسين، بقدر ما أرادوا. وكذلك فعل بالسمكتين.","6:12":"فلما شبعوا، قال لتلاميذه: «اجمعوا كسر الخبز التي فضلت لكي لا يضيع شيء!»","6:13":"فجمعوها، وملأوا اثنتي عشرة قفة من كسر الخبز الفاضلة عن الآكلين من خمسة أرغفة الشعير.","6:14":"فلما رأى الناس الآية التي صنعها يسوع قالوا: «حقا، هذا هو النبي الآتي إلى العالم».","6:15":"وعلم يسوع أنهم على وشك أن يختطفوه ليقيموه ملكا، فعاد إلى الجبل وحده.","6:16":"ولما حل المساء نزل تلاميذه إلى البحيرة،","6:17":"وركبوا قاربا متجهين إلى كفرناحوم في الضفة المقابلة من البحيرة. وخيم الظلام ولم يكن يسوع قد لحق بهم.","6:18":"وهبت عاصفة قوية، فاضطربت البحيرة.","6:19":"وبعدما جذف التلاميذ نحو ثلاثة أميال أو أربعة، رأوا يسوع يقترب من القارب ماشيا على ماء البحيرة، فاستولى عليهم الخوف،","6:20":"فشجعهم قائلا: «أنا هو لا تخافوا!»","6:21":"فما كادوا يطلبون منه أن يصعد إلى القارب، حتى وصل القارب إلى المكان المقصود.","6:22":"وفي اليوم التالي، لم يجد الجمع الذين باتوا على الضفة المقابلة من البحيرة إلا قاربا واحدا. وكانوا يعرفون أن يسوع لم يركب القارب مع تلاميذه (بالأمس)، بل استقله التلاميذ وحدهم.","6:23":"ثم جاءت قوارب أخرى من طبرية، ورست بالقرب من المكان الذي أكلوا فيه الخبز بعدما شكر الرب عليه.","6:24":"فلما لم يجد الجمع يسوع ولا تلاميذه هناك، ركبوا تلك القوارب وجاءوا إلى كفرناحوم باحثين عن يسوع.","6:25":"فلما وجدوه على الضفة المقابلة من البحيرة، قالوا له: «يامعلم، متى وصلت إلى هنا؟»","6:26":"أجابهم يسوع: «الحق الحق أقول لكم: أنتم تبحثون عني لا لأنكم رأيتم الآيات، بل لأنكم أكلتم وشبعتم من تلك الأرغفة.","6:27":"لا تسعوا وراء الطعام الفاني، بل وراء الطعام الباقي إلى الحياة الأبدية، والذي يعطيكم إياه ابن الإنسان، لأن هذا الطعام قد وضع الله الآب ختمه عليه».","6:28":"فسألوه: «ماذا نفعل لنعمل ما يطلبه الله؟»","6:29":"أجاب يسوع: «العمل الذي يطلبه الله هو أن تؤمنوا بمن أرسله».","6:30":"فقالوا له: «ما الآية التي تعملها لنراها ونؤمن بك؟ ماذا تقدر أن تعمل؟","6:31":"فإن آباءنا أكلوا المن في البرية كما جاء في الكتاب: أعطاهم من السماء خبزا ليأكلوا!»","6:32":"فأجابهم يسوع: «الحق الحق أقول لكم: إن موسى لم يعطكم خبزا من السماء، وإنما أبي هو الذي يعطيكم الآن خبز السماء الحقيقي،","6:33":"فخبز الله هو النازل من السماء الواهب حياة للعالم».","6:34":"قالوا له: «ياسيد، أعطنا في كل حين هذا الخبز».","6:35":"فأجابهم يسوع: «أنا هو خبز الحياة. فالذي يقبل إلي لا يجوع، والذي يؤمن بي لا يعطش أبدا.","6:36":"ولكن قلت لكم إنكم رأيتموني ولا تؤمنون،","6:37":"ولكن كل ما يهبه الآب لي سيأتي إلي، ومن يأت إلي لا أطرحه إلى الخارج أبدا،","6:38":"فقد نزلت من السماء، لا لأتم مشيئتي، بل مشيئة الذي أرسلني.","6:39":"ومشيئته هي أن لا أدع أحدا ممن وهبهم لي يهلك، بل أقيمه في اليوم الأخير.","6:40":"نعم! إن مشيئة أبي هي أن كل من يرى الابن ويؤمن به تكون له الحياة الأبدية، وسأقيمه أنا في اليوم الأخير».","6:41":"فأخذ اليهود يتذمرون على يسوع لأنه قال: «أنا الخبز الذي نزل من السماء».","6:42":"وقالوا: «أليس هذا يسوع ابن يوسف، الذي نعرف نحن أباه وأمه، فكيف يقول: إني نزلت من السماء؟»","6:43":"فأجابهم يسوع: «لا تتذمروا فيما بينكم!","6:44":"لا يقدر أحد أن يأتي إلي إلا إذا اجتذبه الآب الذي أرسلني. وأنا أقيمه في اليوم الأخير.","6:45":"جاء في كتب الأنبياء: سيتعلم الجميع من الله. وكل من يسمع الآب ويتعلم منه يأتي إلي.","6:46":"وليس معنى هذا أن أحدا رأى الآب: فما رآه إلا الذي كان مع الله. هو وحده رأى الآب.","6:47":"الحق الحق أقول لكم: إن الذي يؤمن بي فله حياة أبدية.","6:48":"أنا هو خبز الحياة.","6:49":"أكل أباؤكم المن في البرية ثم ماتوا،","6:50":"ولكن ها هنا الخبز النازل من السماء ليأكل منه الإنسان فلا يموت.","6:51":"أنا الخبز الحي الذي نزل من السماء. إن أكل أحد من هذا الخبز يحيا إلى الأبد. والخبز الذي أقدمه أنا، هو جسدي، أبذله من أجل أن يحيا العالم».","6:52":"فأثار هذا الكلام جدالا عنيفا بين اليهود، وتساءلوا: «كيف يقدر هذا أن يعطينا جسده لنأكله؟»","6:53":"فأجابهم يسوع: «الحق الحق أقول لكم: إذا لم تأكلوا جسد ابن الإنسان وتشربوا دمه فلا حياة لكم في داخلكم.","6:54":"من يأكل جسدي ويشرب دمي، فله حياة أبدية، وأنا أقيمه في اليوم الأخير،","6:55":"لأن جسدي هو الطعام الحقيقي، ودمي هو الشراب الحقيقي.","6:56":"وكل من يأكل جسدي ويشرب دمي، يثبت في وأنا فيه.","6:57":"وكما أني أحيا بالآب الحي الذي أرسلني، فكذلك يحيا بي من يأكلني.","6:58":"هذا هو الخبز الذي نزل من السماء، وهو ليس كالمن الذي أكله أباؤكم ثم ماتوا. فالذي يأكل هذا الخبز يحيا إلى الأبد».","6:59":"هذا كله قاله يسوع في المجمع وهو يعلم في كفرناحوم.","6:60":"فلما سمعه كثيرون من تلاميذه قالوا: «ما أصعب هذا الكلام! من يطيق سماعه؟»","6:61":"فعلم يسوع في نفسه أن تلاميذه يتذمرون، فسألهم: «أهذا يبعث الشكوك في نفوسكم؟","6:62":"فماذا لو رأيتم ابن الإنسان صاعدا إلى حيث كان قبلا؟","6:63":"الروح هو الذي يعطي الحياة، أما الجسد فلا يفيد شيئا. الكلام الذي كلمتكم به هو روح وحياة.","6:64":"ولكن بعضا منكم لا يؤمنون!» فقد كان يسوع منذ البدء يعرف من هم الذين لا يؤمنون به، ومن هو الذي سيخونه.","6:65":"ثم قال: «لذلك قلت لكم: لا يقدر أحد أن يأتي إلي إلا إذا وهبه الآب ذلك».","6:66":"من ذلك الوقت هجره كثيرون من أتباعه، ولم يعودوا يتبعونه!","6:67":"فقال للاثني عشر تلميذا: «وأنتم أتريدون أن تذهبوا مثلهم؟»","6:68":"فأجابه سمعان بطرس: «إلى من نذهب يارب وعندك كلام الحياة الأبدية.","6:69":"نحن آمنا وعرفنا أنك قدوس الله!»","6:70":"فقال يسوع: «أليس أنا اخترتكم أنتم الاثني عشر، ومع ذلك فواحد منكم شيطان؟»","6:71":"أشار بهذا إلى يهوذا بن سمعان الإسخريوطي، لأنه من الاثني عشر!","7:1":"بعد ذلك بدأ يسوع يتنقل في منطقة الجليل، متجنبا التجول في منطقة اليهودية، لأن اليهود كانوا يسعون إلى قتله.","7:2":"وعندما اقترب عيد المظال اليهودي،","7:3":"قال له إخوته: «اترك هذه المنطقة واذهب إلى اليهودية ليرى أتباعك ما تعمله من أعمال،","7:4":"فلا أحد يعمل في الخفاء إذا كان يبتغي الشهرة. وما دمت تعمل هذه الأعمال، فأظهر نفسك للعالم».","7:5":"فإن إخوته لم يكونوا مؤمنين به.","7:6":"فأجابهم يسوع: «ما حان وقتي بعد، أما وقتكم فهو مناسب كل حين.","7:7":"لا يقدر العالم أن يبغضكم، ولكنه يبغضني أنا، لأني أشهد عليه أن أعماله شريرة.","7:8":"اصعدوا أنتم إلى العيد، أما أنا فلن أصعد الآن إلى هذا العيد لأن وقتي ما جاء بعد».","7:9":"قال لهم هذا وبقي في الجليل.","7:10":"وبعدما ذهب إخوته إلى العيد، ذهب هو أيضا كما لو كان متخفيا، لا ظاهرا.","7:11":"فأخذ اليهود يبحثون عنه في العيد، ويسألون: «أين ذاك الرجل؟»","7:12":"وثارت بين الجموع مناقشات كثيرة حوله، فقال بعضهم: «إنه صالح» وقال آخرون: «لا! بل إنه يضلل الشعب»","7:13":"ولكن لم يجرؤ أحد أن يتكلم عنه علنا، خوفا من اليهود.","7:14":"ولما مضى من العيد نصفه، صعد يسوع إلى الهيكل وبدأ يعلم الناس.","7:15":"فدهش اليهود وتساءلوا «كيف يعرف هذا الكتب وهو لم يتعلم؟»","7:16":"فأجابهم يسوع: «ليس تعليمي من عندي، بل من عند الذي أرسلني","7:17":"ومن أراد أن يعمل مشيئة الله يعرف ما إذا كان تعليمي من عند الله، أو أنني أتكلم من عندي.","7:18":"من يتكلم من عنده يطلب المجد لنفسه؛ أما الذي يطلب المجد لمن أرسله فهو صادق لا إثم فيه.","7:19":"أما أعطاكم موسى الشريعة؟ ولكن ما من أحد منكم يعمل بالشريعة! لماذا تسعون إلى قتلي؟»","7:20":"أجابه الجمع: «بك شيطان! من يريد أن يقتلك؟»","7:21":"فقال يسوع: «عملت يوم السبت عملا واحدا فاستغربتم جميعا.","7:22":"إن موسى أوصاكم بالختان وهذا لا يعني أن الختان يرجع إلى موسى بل إلى الآباء ولذلك تختنون الإنسان ولو يوم السبت.","7:23":"فإن كنتم تجرون الختان للإنسان يوم السبت لكي لا تخالفوا شريعة موسى، فهل تغضبون علي لأني شفيت إنسانا بكامله في السبت؟","7:24":"لا تحكموا بحسب الظاهر، بل احكموا حكما عادلا».","7:25":"عند ذلك قال بعض أهل أورشليم: «أليس هذا هو الذي يريدون أن يقتلوه؟","7:26":"ها هو يتكلم علنا ولا أحد يعترضه بشيء. ترى، هل تأكد رؤساؤنا أنه هو المسيح حقا؟","7:27":"إن المسيح عندما يأتي لن يعرف أحد من أين جاء، أما هذا فإننا نعرف أصله!»","7:28":"فرفع يسوع صوته، وهو يعلم في الهيكل، قائلا: «أنتم تعرفونني وتعرفون من أين أنا! وأنا لم آت من عند ذاتي، ولكن الذي أرسلني هو حق وأنتم لا تعرفونه.","7:29":"أما أنا فأعرفه، لأني منه وهو الذي أرسلني».","7:30":"فسعى اليهود للقبض عليه، ولكن أحدا لم يلق عليه يدا، لأن ساعته لم تكن قد حانت.","7:31":"على أن كثيرين من الجمع آمنوا به، وقالوا: «ألعل المسيح، عندما يأتي، يجري آيات أكثر من هذه التي يجريها هذا الرجل؟»","7:32":"وسمع الفريسيون ما يتهامس به الجمع عنه، فأرسلوا هم ورؤساء الكهنة بعض الحراس ليلقوا القبض عليه.","7:33":"فقال لهم يسوع: «أنا باق معكم وقتا قليلا، ثم أعود إلى الذي أرسلني.","7:34":"عندئذ تسعون في طلبي ولا تجدونني، ولا تقدرون أن تذهبوا إلى حيث أكون».","7:35":"فتساءل اليهود فيما بينهم: «إلى أين ينوي أن يذهب فلا نجده؟ أيذهب إلى المدن اليونانية التي تشتت فيها اليهود، ويعلم اليونانيين؟","7:36":"وماذا يعني بقوله: تسعون في طلبي فلا تجدونني، ولا تقدرون أن تذهبوا إلى حيث أكون؟»","7:37":"وفي آخر يوم من العيد، وهو أعظم أيامه، وقف يسوع وقال بأعلى صوته: «إن عطش أحد فليأت إلي ويشرب.","7:38":"وكما قال الكتاب، فمن آمن بي تجري من داخله أنهار ماء حي».","7:39":"قال يسوع هذا عن الروح القدس الذي كان المؤمنون به سيقبلونه. ولم يكن الروح قد أعطي بعد لأن يسوع لم يكن قد تمجد بعد.","7:40":"ولما سمع الحاضرون هذا الكلام قال بعضهم: «هذا هو النبي حقا».","7:41":"وقال آخرون: «هذا هو المسيح». ولكن بعضهم قالوا: «وهل يطلع المسيح من الجليل؟","7:42":"أما قال الكتاب إن المسيح سيأتي من نسل داود، ومن قرية بيت لحم حيث كان داود؟»","7:43":"وهكذا حصل بسببه بين الجمع انقسام في الرأي.","7:44":"وأراد بعضهم أن يلقوا القبض عليه؛ ولكن أحدا لم يلق عليه يدا.","7:45":"ورجع حراس الهيكل إلى الفريسيين ورؤساء الكهنة، فسألوهم: «لماذا لم تحضروه؟»","7:46":"فأجابوا: «لم نسمع قط إنسانا يتكلم بمثل كلامه!»","7:47":"فردوا غاضبين: «وهل ضللتم أنتم أيضا؟","7:48":"أرأيتم أحدا من الرؤساء أو من الفريسيين آمن به؟","7:49":"أما عامة الشعب الذين يجهلون الشريعة، فاللعنة عليهم!»","7:50":"ولكن واحدا منهم، وهو نيقوديموس الذي كان قد جاء إلى يسوع ليلا،","7:51":"قال لهم: «أتسمح شريعتنا بأن يحكم على أحد دون سماع دفاعه أولا لمعرفة ذنبه؟»","7:52":"فأجابوه: «ألعلك أنت أيضا من الجليل؟ ادرس الكتاب تعلم أنه لم يطلع قط نبي من الجليل!»","7:53":"ثم انصرف كل واحد إلى بيته.","8:1":"وأما يسوع، فذهب إلى جبل الزيتون.","8:2":"وعند الفجر عاد إلى الهيكل، فاجتمع حوله جمهور الشعب، فجلس يعلمهم.","8:3":"وأحضر إليه معلمو الشريعة والفريسيون امرأة ضبطت تزني، وأوقفوها في الوسط،","8:4":"وقالوا له: «يامعلم، هذه المرأة ضبطت وهي تزني.","8:5":"وقد أوصانا موسى في شريعته بإعدام أمثالها رجما بالحجارة، فما قولك أنت؟»","8:6":"سألوه ذلك لكي يحرجوه فيجدوا تهمة يحاكمونه بها. أما هو فانحنى وبدأ يكتب بإصبعه على الأرض.","8:7":"ولكنهم ألحوا عليه بالسؤال، فاعتدل وقال لهم: «من كان منكم بلا خطيئة فليرمها أولا بحجر!»","8:8":"ثم انحنى وعاد يكتب على الأرض.","8:9":"فلما سمعوا هذا الكلام انسحبوا جميعا واحدا تلو الآخر، ابتداء من الشيوخ. وبقي يسوع وحده، والمرأة واقفة في مكانها.","8:10":"فاعتدل وقال لها: «أين هم أيتها المرأة؟ ألم يحكم عليك أحد منهم؟»","8:11":"أجابت: «لا أحد ياسيد». فقال لها: «وأنا لا أحكم عليك. اذهبي ولا تعودي تخطئين!»","8:12":"وخاطبهم يسوع أيضا فقال: «أنا نور العالم. من يتبعني فلا يتخبط في الظلام بل يكون له نور الحياة».","8:13":"فاعترضه الفريسيون قائلين: «أنت الآن تشهد لنفسك، فشهادتك لا تصح».","8:14":"فأجاب: «مع أني أشهد لنفسي فإن شهادتي صحيحة، لأنني أعرف من أين أتيت وإلى أين أذهب؛ أما أنتم فلا تعرفون لا من أين أتيت ولا إلى أين أذهب.","8:15":"ولذلك تحكمون علي بحسب البشر، أما أنا فلا أحكم على أحد،","8:16":"مع أنه لو حكمت لجاء حكمي عادلا، لأني لا أحكم بمفردي، بل أنا والآب الذي أرسلني.","8:17":"ومكتوب في شريعتكم أن شهادة شاهدين صحيحة:","8:18":"فأنا أشهد لنفسي، ويشهد لي الآب الذي أرسلني».","8:19":"فسألوه: «أين أبوك؟» فأجاب: «أنتم لا تعرفونني، ولا تعرفون أبي. ولو عرفتموني لعرفتم أبي أيضا».","8:20":"قال يسوع هذا الكلام في الهيكل عند صندوق التقدمات. ولم يلق أحد القبض عليه، لأن ساعته لم تكن قد حانت بعد.","8:21":"ثم قال لهم يسوع: «سوف أذهب فتسعون في طلبي، ولكنكم لا تقدرون أن تأتوا إلى حيث أكون، بل تموتون في خطيئتكم».","8:22":"فأخذ اليهود يتساءلون: «ترى، ماذا يعني قوله لا تقدرون أن تأتوا إلى حيث أكون؟ هل سينتحر؟»","8:23":"فكان رده: «أنتم من تحت. أما أنا فمن فوق. أنتم من هذا العالم. وأنا لست منه.","8:24":"لذلك قلت لكم: ستموتون في خطاياكم، لأنكم إذا لم تؤمنوا بأني أنا هو، تموتون في خطاياكم».","8:25":"فسألوه: «من أنت؟» أجاب يسوع: «قلت لكم من البداية!","8:26":"وعندي أشياء كثيرة أقولها وأحكم بها عليكم. ولكن الذي أرسلني هو حق، وما أقوله للعالم هو ما سمعته منه».","8:27":"ولم يفهموا أن يسوع، بقوله هذا، كان يشير إلى الآب.","8:28":"لذلك قال لهم يسوع: «عندما تعلقون ابن الإنسان تعرفون أني أنا هو، وأني لا أعمل شيئا من نفسي، بل أقول الكلام الذي علمني إياه أبي.","8:29":"إن الذي أرسلني هو معي، ولم يتركني وحدي، لأني دوما أعمل ما يرضيه».","8:30":"وبينما يسوع يتكلم بهذا، آمن به كثيرون.","8:31":"فقال لليهود الذين آمنوا به: «إن ثبتم في كلمتي، كنتم حقا تلاميذي.","8:32":"وتعرفون الحق، والحق يحرركم».","8:33":"فرد اليهود: «نحن أحفاد إبراهيم، ولم نكن قط عبيدا لأحد! كيف تقول لنا: إنكم ستصيرون أحرارا؟»","8:34":"أجابهم يسوع: «الحق الحق أقول لكم: إن من يرتكب الخطيئة يكون عبدا لها.","8:35":"والعبد لا يبقى في بيت سيده دائما؛ أما الابن فيعيش فيه أبدا.","8:36":"فإن حرركم الابن تصيرون بالحق أحرارا.","8:37":"أنا أعرف أنكم أحفاد إبراهيم. ولكنكم تسعون إلى قتلي، لأن كلمتي لا تجد لها مكانا في قلوبكم.","8:38":"إني أتكلم بما رأيته عند الآب، وأنتم تعملون بما سمعتم من أبيكم».","8:39":"فاعترضوه قائلين: «أبونا هو إبراهيم!» فقال لو كنتم أولاد إبراهيم لعملتم أعمال إبراهيم.","8:40":"ولكنكم تسعون إلى قتلي وأنا إنسان كلمتكم بالحق الذي سمعته من الله. وهذا لم يفعله إبراهيم.","8:41":"أنتم تعملون أعمال أبيكم!» فقالوا له: «نحن لم نولد من زنا! لنا أب واحد هو الله».","8:42":"فقال يسوع: «لو كان الله أباكم لكنتم تحبونني، لأني خرجت من الله وجئت. لم آت من نفسي، بل هو الذي أرسلني.","8:43":"لماذا لا تفهمون كلامي؟ لأنكم لا تطيقون سماع كلمتي!","8:44":"إنكم أولاد أبيكم إبليس، وترغبون أن تعملوا شهوات أبيكم. فهو من البدء كان قاتلا للناس، ولم يثبت في الحق لأنه خال من الحق! وعندما ينطق بالكذب فهو ينضح بما فيه، لأنه كذاب وأبو الكذب!","8:45":"أما أنا فلأني أقول الحق، لستم تصدقونني.","8:46":"من منكم يثبت علي خطيئة؟ فما دمت أقول الحق، فلماذا لا تصدقونني؟","8:47":"من كان من الله حقا، يسمع كلام الله. ولكنكم ترفضون كلام الله، لأنكم لستم من الله!»","8:48":"فقال اليهود: «ألسنا نقول الحق عندما نقول إنك سامري وإن فيك شيطانا؟»","8:49":"أجابهم: «لا شيطان في، لكني أكرم أبي وأنتم تهينونني.","8:50":"أنا لا أطلب مجد نفسي، فهناك من يطالب ويقضي لي.","8:51":"الحق الحق أقول لكم: إن من يطيع كلامي لن يرى الموت أبدا».","8:52":"فقال اليهود: «الآن تأكد لنا أن فيك شيطانا. مات إبراهيم ومات الأنبياء، وأنت تقول إن الذي يطيع كلامك لن يذوق الموت أبدا.","8:53":"أأنت أعظم من أبينا إبراهيم الذي مات؟ حتى الأنبياء ماتوا؛ فمن تجعل نفسك؟»","8:54":"أجابهم: «إن كنت أمجد نفسي، فليس مجدي بشيء. لكن أبي هو الذي يمجدني. وأنتم تقولون إنه إلهكم،","8:55":"مع أنكم لا تعرفونه. أما أنا فأعرفه. ولو قلت لكم إني لا أعرفه لكنت مثلكم كاذبا. لكني أعرفه وأعمل بكلمته.","8:56":"أبوكم إبراهيم ابتهج لرجائه أن يرى يومي، فرآه وفرح»","8:57":"فقال له اليهود: «ليس لك من العمر خمسون سنة بعد فكيف رأيت إبراهيم؟»","8:58":"أجابهم: الحق الحق أقول لكم: إنني كائن من قبل أن يكون إبراهيم».","8:59":"فرفعوا حجارة ليرجموه، ولكنه أخفى نفسه وخرج من الهيكل.","9:1":"وفيما كان يسوع مارا، رأى رجلا أعمى منذ ولادته،","9:2":"فسأله تلاميذه: «يامعلم، من أخطأ: هذا أم والداه، حتى ولد أعمى؟»","9:3":"فأجابهم يسوع: «لا هو أخطأ ولا والداه، ولكن حتى تظهر فيه أعمال الله.","9:4":"فعلي أن أعمل أعمال الذي أرسلني مادام الوقت نهارا. فسيأتي الليل، ولا أحد يقدر أن يعمل فيه.","9:5":"وما دمت في العالم، فأنا نور العالم».","9:6":"قال هذا، وتفل في التراب، وجبل من التفل طينا، ثم وضعه على عيني الأعمى،","9:7":"وقال له: «اذهب اغتسل في بركة سلوام» (أي الرسول). فذهب واغتسل وعاد بصيرا.","9:8":"فتساءل الجيران والذين كانوا يرونه من قبل يستعطي: «أليس هذا هو نفسه الذي كان يجلس ليستعطي؟»","9:9":"قال بعضهم: «هذا هو». وآخرون: «لا ... ولكنه يشبهه!» أما هو فرد قائلا: «بل أنا هو!»","9:10":"فقالوا له: «وكيف انفتحت عيناك؟»","9:11":"أجاب: «الرجل الذي اسمه يسوع جبل طينا دهن به عيني، وقال لي: اذهب إلى بركة سلوام واغتسل فيها. فذهبت واغتسلت فأبصرت!»","9:12":"فسألوه: «وأين هو الآن؟» فقال: «لا أعرف!»","9:13":"فذهبوا بالرجل الذي كان أعمى إلى الفريسيين.","9:14":"وكان اليوم الذي جبل فيه يسوع الطين وفتح عيني الأعمى، يوم سبت.","9:15":"فسأله الفريسيون أيضا كيف أبصر. فأجاب: «وضع طينا على عيني، واغتسلت، وها أنا أبصر!»","9:16":"فقال بعض الفريسيين: «لا يمكن أن يكون هذا الرجل من الله، لأنه يخالف سنة السبت». ولكن بعضهم قالوا: «كيف يقدر رجل خاطئ أن يعمل مثل هذه الآيات؟» فوقع الخلاف بينهم.","9:17":"وعادوا يسألون الذي كان أعمى: «وما رأيك أنت فيه مادام قد فتح عينيك؟» فأجابهم: «إنه نبي!»","9:18":"ورفض اليهود أن يصدقوا أنه كان أعمى فأبصر، فاستدعوا والديه","9:19":"وسألوهما: «أهذا ابنكما المولود أعمى كما تقولان؟ فكيف يبصر الآن؟»","9:20":"أجابهم الوالدان: «نعلم أن هذا ابننا وأنه ولد أعمى.","9:21":"ولكننا لا نعلم كيف يبصر الآن، ولا من فتح عينيه. إنه بالغ الرشد، يجيبكم عن نفسه، فاسألوه!»","9:22":"وقد قال والداه هذا لخوفهما من اليهود، لأن اليهود كانوا قد اتفقوا أن يطردوا من المجمع كل من يعترف أن يسوع هو المسيح.","9:23":"لذلك قالا: «إنه بالغ الرشد فاسألوه».","9:24":"ثم استدعى الفريسيون، مرة ثانية الرجل الذي كان أعمى، وقالوا له: «مجد الله! نحن نعلم أن هذا الرجل خاطئ».","9:25":"فأجاب: «أخاطئ هو، لست أعلم! إنما أعلم شيئا واحدا: أني كنت أعمى والآن أبصر!»","9:26":"فسألوه ثانية: «ماذا فعل بك؟ كيف فتح عينيك؟»","9:27":"أجابهم: «قد قلت لكم ولم تسمعوا لي، فلماذا تريدون أن تسمعوا مرة ثانية؟ ألعلكم تريدون أنتم أيضا أن تصيروا تلاميذ له؟»","9:28":"فشتموه وقالوا له: «بل أنت تلميذه! أما نحن فتلاميذ موسى.","9:29":"نحن نعلم أن موسى كلمه الله؛ أما هذا، فلا نعلم له أصلا!»","9:30":"فأجابهم الرجل: «إن في ذلك عجبا! إنه فتح عيني، وتقولون إنكم لا تعلمون له أصلا!","9:31":"نحن نعلم أن الله لا يستجيب للخاطئين، ولكنه يستمع لمن يتقيه ويعمل بإرادته،","9:32":"ولم يسمع على مدى الأجيال أن أحدا فتح عيني مولود أعمى!","9:33":"فلو لم يكن هو من الله، لما استطاع أن يعمل شيئا».","9:34":"فصاحوا به: «أنت بكاملك ولدت في الخطيئة وتعلمنا؟!» ثم طردوه خارج المجمع.","9:35":"وعرف يسوع بطرده خارجا، فقصد إليه وسأله: «أتؤمن بابن الله؟»","9:36":"أجاب: «من هو ياسيد حتى أومن به؟»","9:37":"فقال له يسوع: «الذي قد رأيته، والذي يكلمك، هو نفسه!»","9:38":"فقال: «أنا أومن ياسيد!» وسجد له.","9:39":"فقال يسوع: «لدينونة أتيت إلى هذا العالم: ليبصر العميان، ويعمى المبصرون!»","9:40":"فسمع ذلك بعض الفريسيين الذين كانوا معه فسألوه: «وهل نحن أيضا عميان؟»","9:41":"فأجابهم يسوع: «لو كنتم عميانا بالفعل، لما كانت عليكم خطيئة. ولكنكم تدعون أنكم تبصرون، ولذلك فإن خطيئتكم باقية...»","10:1":"الحق الحق أقول لكم: إن من يدخل إلى حظيرة الخراف من غير بابها فيتسلق إليها من طريق آخر، فهو سارق ولص.","10:2":"أما الذي يدخل من الباب فهو راعي الخراف،","10:3":"والبواب يفتح له، والخراف تصغي إلى صوته، فينادي خرافه الخاصة كل واحد باسمه، ويقودها إلى خارج الحظيرة.","10:4":"ومتى أخرجها كلها، يسير أمامها وهي تتبعه، لأنها تعرف صوته.","10:5":"وهي لا تتبع من كان غريبا، بل تهرب منه، لأنها لا تعرف صوت الغرباء».","10:6":"ضرب يسوع لهم هذا المثل، ولكنهم لم يفهموا مغزى كلامه.","10:7":"لذلك عاد فقال: «الحق الحق أقول لكم: أنا باب الخراف.","10:8":"جميع الذين جاءوا قبلي كانوا لصوصا وسراقا، ولكن الخراف لم تصغ إليهم.","10:9":"أنا الباب. من دخل بي يخلص، فيدخل ويخرج ويجد المرعى.","10:10":"السارق لا يأتي إلا ليسرق ويذبح ويهلك. أما أنا فقد أتيت لتكون لهم حياة، بل ملء الحياة!","10:11":"أنا الراعي الصالح، والراعي الصالح يبذل حياته فدى خرافه.","10:12":"وليس الأجير كالراعي، لأن الخراف ليست ملكه. فعندما يرى الذئب قادما، يترك الخراف لينجو بنفسه، فيخطف الذئب الخراف ويبددها.","10:13":"إنه يهرب لأنه أجير ولا يبالي بالخراف!","10:14":"أما أنا فإني الراعي الصالح، وأعرف خرافي، وخرافي تعرفني،","10:15":"مثلما يعرفني الآب وأنا أعرفه. وأنا أبذل حياتي فدى خرافي.","10:16":"ولي خراف أخرى لا تنتمي إلى هذه الحظيرة، لا بد أن أجمعها إلي أيضا، فتصغي لصوتي؛ فيكون هناك قطيع واحد وراع واحد.","10:17":"إن الآب يحبني لأني أبذل حياتي لكي أستردها.","10:18":"لا أحد ينتزع حياتي مني، بل أنا أبذلها باختياري. فلي السلطة أن أبذلها ولي السلطة أن أستردها. هذه الوصية تلقيتها من أبي».","10:19":"فانقسم اليهود في الرأي حول هذا الكلام.","10:20":"فقال كثيرون منهم: «إن شيطانا يسكنه، وهو يهذي. فلماذا تستمعون إليه؟»","10:21":"وقال آخرون: «ليس هذا كلام من يسكنه شيطان. أيستطيع الشيطان أن يفتح عيون العميان؟»","10:22":"وفي أثناء الاحتفال بعيد تجديد الهيكل، في الشتاء،","10:23":"كان يسوع يتمشى في الهيكل في قاعة سليمان.","10:24":"فتجمع حوله اليهود وقالوا له: «حتى متى تبقينا حائرين بشأنك؟ إن كنت أنت المسيح حقا، فقل لنا صراحة».","10:25":"فأجابهم يسوع: «قلت لكم، ولكنكم لا تصدقون. والأعمال التي أعملها باسم أبي، هي تشهد لي.","10:26":"ولكنكم لا تصدقون لأنكم لستم خرافي.","10:27":"فخرافي تصغي لصوتي، وأنا أعرفها وهي تتبعني،","10:28":"وأعطيها حياة أبدية، فلا تهلك إلى الأبد، ولا ينتزعها أحد من يدي.","10:29":"إن الآب الذي أعطاني إياها هو أعظم من الجميع، ولا يقدر أحد أن ينتزع من يد الآب شيئا.","10:30":"أنا والآب واحد!»","10:31":"فرفع اليهود، مرة ثانية، حجارة ليرجموه.","10:32":"فقال لهم يسوع: «أريتكم أعمالا صالحة كثيرة من عند أبي، فبسبب أي عمل منها ترجمونني؟»","10:33":"أجابوه: «لا نرجمك بسبب أي عمل صالح، بل بسبب تجديفك: لأنك تجعل نفسك الله، وأنت إنسان!»","10:34":"فقال لهم يسوع: «أليس مكتوبا في شريعتكم: أنا قلت إنكم آلهة؟","10:35":"فإذا كانت الشريعة تدعو أولئك الذين نزلت إليهم كلمة الله آلهة والكتاب لا يمكن أن ينقض","10:36":"فهل تقولون لمن قدسه الآب وبعثه إلى العالم: أنت تجدف، لأني قلت: أنا ابن الله؟","10:37":"إن كنت لا أعمل أعمال أبي، فلا تصدقوني.","10:38":"أما إن كنت أفعل ذلك، فصدقوا تلك الأعمال، إن كنتم لا تصدقونني أنا. عندئذ تعرفون ويتأكد لكم أن الآب في وأنا فيه».","10:39":"فأرادوا ثانية أن يلقوا القبض عليه، ولكنه أفلت من أيديهم،","10:40":"ورجع إلى الضفة المقابلة من نهر الأردن، حيث كان يوحنا يعمد من قبل، وأقام هناك.","10:41":"فجاء إليه كثيرون وهم يقولون: «ما عمل يوحنا آية واحدة، ولكن كل ما قاله عن هذا الرجل كان حقا!»","10:42":"وآمن به كثيرون هناك.","11:1":"ولكن، مرض إنسان اسمه لعازر، وهو من بيت عنيا قرية مريم ومرثا أختها.","11:2":"ومريم هذه هي التي دهنت الرب بالعطر ومسحت قدميه بشعرها وكان لعازر المريض أخاها.","11:3":"فأرسلت الأختان إلى يسوع تقولان: «ياسيد، إن الذي تحبه مريض».","11:4":"فلما سمع بذلك قال: «لن ينتهي هذا المرض بالموت، بل سيؤدي إلى تمجيد الله، إذ به سيتمجد ابن الله».","11:5":"ومع أن يسوع كان يحب مرثا وأختها ولعازر،","11:6":"فقد مكث حيث كان مدة يومين بعد علمه بمرض لعازر.","11:7":"وبعد ذلك قال لتلاميذه: «لنرجع إلى اليهودية!»","11:8":"فقال التلاميذ: «يامعلم، أترجع إلى اليهودية، ومنذ وقت قريب أراد اليهود أن يرجموك؟»","11:9":"فأجاب يسوع: «أليست ساعات النهار اثنتي عشرة؟ فالذي يمشي في النهار لا يتعثر لأنه يرى نور هذا العالم.","11:10":"أما الذي يمشي في الليل فإنه يتعثر، لأن النور ليس فيه».","11:11":"ثم قال يسوع: «لعازر حبيبنا قد رقد، ولكني سأذهب لأنهضه».","11:12":"فقال التلاميذ: «ياسيد، إن كان قد رقد، فإنه سينهض معافى».","11:13":"وكان يسوع يعني موت لعازر؛ أما التلاميذ فظنوه يعني رقاد النوم.","11:14":"عندئذ قال لهم صراحة: «لعازر قد مات.","11:15":"ولأجلكم أنا أفرح بأني لم أكن هناك، حتى تؤمنوا. فلنذهب إليه!»","11:16":"فقال توما، المعروف بالتوأم، للتلاميذ الآخرين: «لنذهب نحن أيضا فنقتل معه!» (أي مع يسوع).","11:17":"وعندما وصل يسوع إلى بيت عنيا كان لعازر قد دفن منذ أربعة أيام.","11:18":"وكانت بيت عنيا لا تبعد عن أورشليم إلا حوالي ميلين.","11:19":"وكان كثيرون من اليهود قد توافدوا إلى مرثا ومريم يعزونهما عن أخيهما.","11:20":"فلما عرفت مرثا أن يسوع قادم خرجت للقائه، وبقيت مريم جالسة في البيت.","11:21":"وقالت مرثا ليسوع: «ياسيد، لو كنت هنا، لما مات أخي.","11:22":"فأنا واثقة تماما بأن الله يعطيك كل ما تطلب منه».","11:23":"فأجاب يسوع: «سيقوم أخوك».","11:24":"قالت مرثا: «أعرف أنه سيقوم في القيامة، في اليوم الأخير!»","11:25":"فرد يسوع: «أنا هو القيامة والحياة. من آمن بي، وإن مات فسيحيا.","11:26":"ومن كان حيا وآمن بي فلن يموت إلى الأبد. أتؤمنين بهذا؟»","11:27":"أجابته: «نعم ياسيد. أنا قد آمنت أنك أنت المسيح ابن الله الذي جاء إلى العالم!»","11:28":"قالت هذا، وذهبت تدعو أختها مريم، فقالت لها سرا: «المعلم هنا، وهو يطلبك!»","11:29":"فلما سمعت مريم هبت واقفة، وأسرعت إلى يسوع.","11:30":"ولم يكن قد وصل بعد إلى القرية، بل كان لايزال في المكان الذي لاقته فيه مرثا.","11:31":"فلما رآها اليهود، الذين كانوا معها في البيت يعزونها، تهب واقفة وتسرع بالخروج، لحقوا بها، لأنهم ظنوا أنها ذاهبة لتبكي عند القبر.","11:32":"وما إن وصلت مريم إلى حيث كان يسوع ورأته، حتى ارتمت على قدميه تقول: «ياسيد، لو كنت هنا، لما مات أخي!»","11:33":"فلما رآها يسوع تبكي ويبكي معها اليهود الذين رافقوها، فاض قلبه بالأسى الشديد،","11:34":"وسأل: «أين دفنتموه؟» فأجابوا: «تعال، ياسيد، وانظر!»","11:35":"عندئذ بكى يسوع.","11:36":"فقال اليهود بعضهم لبعض: «انظروا كم كان يحبه!»","11:37":"وتساءل بعضهم: «ألم يقدر هذا الذي فتح عيني الأعمى أن يرد الموت عن لعازر؟»","11:38":"ففاض قلب يسوع بالأسى الشديد مرة ثانية. ثم اقترب إلى القبر، وكان كهفا على بابه حجر كبير.","11:39":"وقال: «ارفعوا الحجر!» فقالت مرثا: «ياسيد، هذا يومه الرابع، وقد أنتن».","11:40":"فقال يسوع: «ألم أقل لك: إن آمنت ترين مجد الله؟»","11:41":"فرفعوا الحجر، ورفع يسوع عينيه إلى السماء وقال: «أيها الآب، أشكرك لأنك سمعت لي،","11:42":"وقد علمت أنك دوما تسمع لي. ولكني قلت هذا لأجل الجمع الواقف حولي ليؤمنوا أنك أنت أرسلتني».","11:43":"ثم نادى بصوت عال: «لعازر اخرج!»","11:44":"فخرج الميت والأكفان تشد يديه ورجليه، والمنديل يلف رأسه. فقال يسوع لمن حوله: «حلوه ودعوه يذهب!»","11:45":"وآمن بيسوع كثيرون من اليهود الذين جاءوا ليعزوا مريم، عندما رأوه يعمل ذلك.","11:46":"على أن جماعة منهم ذهبوا إلى الفريسيين وأخبروهم بما عمله يسوع.","11:47":"فعقد رؤساء الكهنة والفريسيون مجلسا، وقالوا: «ماذا نفعل؟ هذا الرجل يعمل آيات كثيرة.","11:48":"فإذا تركناه وشأنه يؤمن به الجميع، فيأتي الرومانيون ويدمرون هيكلنا المقدس وأمتنا!»","11:49":"فقال واحد منهم، وهو قيافا الذي كان رئيسا للكهنة في تلك السنة: «إنكم لا تعرفون شيئا!","11:50":"ألا تفهمون أنه من الأفضل أن يموت رجل واحد فدى الأمة، بدلا من أن تهلك الأمة كلها».","11:51":"ولم يقل قيافا هذا الكلام من عنده، ولكن إذ كان رئيسا للكهنة في تلك السنة تنبأ أن يسوع سيموت فدى الأمة،","11:52":"وليس فدى الأمة وحسب بل أيضا ليجمع أبناء الله المشتتين فيجعلهم واحدا.","11:53":"من ذلك اليوم قرر اليهود أن يقتلوا يسوع.","11:54":"فلم يعد يتجول بينهم جهارا، بل ذهب إلى مدينة اسمها أفرايم، تقع في بقعة قريبة من البرية، حيث أقام مع تلاميذه.","11:55":"وكان عيد الفصح اليهودي قد اقترب، فتوافد كثيرون من القرى إلى أورشليم ليقوموا بطقوس التطهر السابقة للعيد.","11:56":"وكانوا يبحثون عن يسوع، ويتساءلون وهم مجتمعون في الهيكل: «ما رأيكم؟ ألعله لا يأتي إلى العيد؟»","11:57":"وكان رؤساء الكهنة والفريسيون قد أصدروا أمرا بأن على كل من يجد يسوع أن يبلغ عنه ليلقوا القبض عليه.","12:1":"وقبل الفصح بستة أيام جاء يسوع إلى بيت عنيا، بلدة لعازر الذي أقامه من بين الأموات.","12:2":"فأقيمت له وليمة عشاء، وأخذت مرثا تخدم، وكان لعازر أحد المتكئين معه.","12:3":"فأخذت مريم منا (أي ثلث لتر) من عطر الناردين الخالص الغالي الثمن، ودهنت به قدمي يسوع، ثم مسحتهما بشعرها، فملأت الرائحة الطيبة أرجاء البيت كله.","12:4":"فقال أحد التلاميذ، وهو يهوذا الإسخريوطي، الذي كان سيخون يسوع:","12:5":"«لماذا لم يبع هذا العطر بثلاث مئة دينار توزع على الفقراء؟»","12:6":"ولم يقل هذا لأنه كان يعطف على الفقراء، بل لأنه كان لصا، فقد كان أمينا للصندوق وكان يختلس مما يودع فيه.","12:7":"فأجابه يسوع: «دعها! فقد احتفظت بهذا العطر ليوم دفني،","12:8":"لأن الفقراء عندكم في كل حين؛ أما أنا فلن أكون عندكم في كل حين».","12:9":"وعلم كثيرون من اليهود أن يسوع في بيت عنيا، فجاءوا لا ليروا يسوع فقط، بل ليروا أيضا لعازر الذي أقامه من بين الأموات.","12:10":"فقرر رؤساء الكهنة أن يقتلوا لعازر أيضا،","12:11":"لأن كثيرين من اليهود كانوا يهجرونهم بسببه ويؤمنون بيسوع.","12:12":"وفي اليوم التالي، عرف الجمهور الكبير الذي جاء إلى العيد أن يسوع قادم إلى أورشليم.","12:13":"فحملوا سعف النخل وخرجوا لاستقباله هاتفين: «أوصنا! تبارك الآتي باسم الرب! إنه ملك إسرائيل!»","12:14":"ووجد يسوع جحشا فركب عليه، كما قد كتب:","12:15":"«لا تخافي يابنت صهيون، فإن ملكك قادم إليك راكبا على جحش أتان».","12:16":"ولم يدرك تلاميذ يسوع أول الأمر أن هذا إتمام للنبوءة. ولكن بعدما تمجد يسوع تذكروا أن الكتاب قال هذا عنه، وأنهم فعلوا هذا من أجله.","12:17":"والجمع الذين كانوا معه حين دعا لعازر من القبر وأقامه من بين الأموات، كانوا يشهدون له بذلك.","12:18":"ولذلك خرجت الجموع لاستقباله، لأنهم سمعوا أنه أجرى تلك الآية.","12:19":"فقال الفريسيون بعضهم لبعض: «أرأيتم كيف أنكم لم تستفيدوا شيئا؟ ها قد انطلق العالم كله وراءه!»","12:20":"وكان بين الذين قصدوا أورشليم للعبادة في أثناء العيد بعض اليونانيين،","12:21":"فذهبوا إلى فيلبس، وهو من بيت صيدا في منطقة الجليل، وقالوا له: «ياسيد، نريد أن نرى يسوع».","12:22":"فجاء فيلبس وأخبر أندراوس، ثم ذهبا معا وأخبرا يسوع.","12:23":"فقال يسوع لهما: «قد اقتربت ساعة تمجيد ابن الإنسان.","12:24":"الحق الحق أقول لكم: إن حبة الحنطة تبقى وحيدة إن لم تقع في الأرض وتمت. أما إذا ماتت، فإنها تنتج حبا كثيرا.","12:25":"من يتمسك بحياته، يخسرها. ومن نبذها في هذا العالم يوفرها للحياة الأبدية.","12:26":"من أراد أن يخدمني فليتبعني. وحيث أكون أنا يكون خادمي أيضا. وكل من يخدمني يكرمه أبي.","12:27":"نفسي الآن مضطربة، فماذا أقول؟ أيها الآب أنقذني من الساعة القادمة علي؟ لا! فمن أجل هذه الساعة أتيت.","12:28":"أيها الآب، مجد اسمك!»","12:29":"فقال بعض الحاضرين ممن سمعوا الصوت: «هذا صوت رعد!» ولكن غيرهم قالوا: «حدثه ملاك».","12:30":"فأجاب يسوع: «لم يكن هذا الصوت لأجلي بل لأجلكم.","12:31":"الآن وقت الحكم على هذا العالم! الآن يطرد سيد هذا العالم خارجا!","12:32":"وحين أعلق مرفوعا عن الأرض أجذب إلي الجميع».","12:33":"قال هذا مشيرا إلى الميتة التي سيموتها.","12:34":"فقال بعض الحاضرين: «علمتنا الشريعة أن المسيح يبقى حيا إلى الأبد، فكيف تقول إن ابن الإنسان لابد أن يعلق؟ من هو ابن الإنسان هذا؟»","12:35":"فقال لهم يسوع: «النور باق معكم وقتا قصيرا. فواصلوا سيركم مادام النور يشرق عليكم، لئلا يطبق عليكم الظلام، فإن الذي يمشي في الظلام لا يعلم أين يذهب.","12:36":"آمنوا بالنور مادام النور معكم، فتصيروا أبناء النور».","12:37":"ومع أنه أجرى أمامهم آيات كثيرة جدا، لم يؤمنوا به،","12:38":"ليتم قول النبي إشعياء: «يارب من آمن بكلامنا؟ ولمن ظهرت يد الرب؟»","12:39":"فلم يستطيعوا أن يؤمنوا، لأن إشعياء قال أيضا:","12:40":"«أعمى عيونهم وقسى قلوبهم، لئلا يبصروا بعيونهم ويفهموا بقلوبهم، ويتوبوا فأشفيهم».","12:41":"وقد قال إشعياء هذا عندما رأى مجد الرب فتحدث عنه.","12:42":"ومع ذلك فإن كثيرين من الرؤساء آمنوا بيسوع، دون أن يجاهروا بإيمانهم، مخافة أن يحكم عليهم بالطرد من المجمع،","12:43":"مفضلين المجد الآتي من الناس على المجد الآتي من الله.","12:44":"فقال يسوع بصوت عال: «من يؤمن بي، فهو يؤمن لا بي أنا بل بالذي أرسلني،","12:45":"ومن رآني، رأى الذي أرسلني","12:46":"جئت إلى العالم نورا، فمن آمن بي لا يبقى في الظلام.","12:47":"وإذا سمع أحد كلامي ولم يؤمن به، فأنا لا أحكم عليه، فقد جئت لا لأحكم على العالم، بل لأخلص العالم.","12:48":"فالذي يرفضني ولا يقبل كلامي، له من يحكم عليه: فإن الكلمة التي قلتها هي تحكم عليه في اليوم الأخير؛","12:49":"لأني لم أتكلم بشيء من عندي، بل أقول ما أوصاني به الآب الذي أرسلني","12:50":"وأنا أعلم أن وصيته هي حياة أبدية: فإن ما أقوله من كلام، أقوله كما قاله لي الآب».","13:1":"وقبيل عيد الفصح، ويسوع عالم أن ساعته قد حانت ليرحل من هذا العالم إلى الآب، فإذ كان قد أحب خاصته الذين في العالم، أحبهم الآن أقصى المحبة:","13:2":"ففي أثناء العشاء، وكان الشيطان قد وضع في قلب يهوذا بن سمعان الإسخريوطي أن يخون يسوع،","13:3":"وكان يسوع عالما أن الآب قد جعل كل شيء في يديه وأنه من الله خرج وإلى الله سيعود،","13:4":"نهض عن مائدة العشاء، وخلع رداءه وأخذ منشفة لفها على وسطه،","13:5":"ثم صب ماء في وعاء للغسل، وبدأ يغسل أقدام التلاميذ ويمسحها بالمنشفة التي على وسطه.","13:6":"فلما وصل إلى سمعان بطرس، قال له سمعان: «ياسيد، أنت تغسل قدمي!»","13:7":"فأجابه يسوع: «أنت الآن لا تفهم ما أعمله، ولكنك ستفهم فيما بعد».","13:8":"ولكن بطرس أصر قائلا: «لا، لن تغسل قدمي أبدا!» فأجابه يسوع: «إن كنت لا أغسلك، فلا يكون لك نصيب معي!»","13:9":"عندئذ قال له سمعان بطرس: «ياسيد، لا قدمي فقط، بل يدي ورأسي أيضا!»","13:10":"فقال يسوع: «من اغتسل صار كله نقيا، ولا يحتاج إلا لغسل قدميه. وأنتم أنقياء، ولكن ليس كلكم».","13:11":"فإن يسوع كان يعلم من الذي سيخونه، ولذلك قال: «لستم كلكم أنقياء».","13:12":"وبعدما انتهى من غسل أقدامهم، أخذ رداءه واتكأ من جديد، وسألهم: «أفهمتم ما عملته لكم؟","13:13":"أنتم تدعونني معلما وسيدا، وقد صدقتم، فأنا كذلك.","13:14":"فإن كنت، وأنا السيد والمعلم، قد غسلت أقدامكم، فعليكم أنتم أيضا أن يغسل بعضكم أقدام بعض.","13:15":"فقد قدمت لكم مثالا لكي تعملوا مثل ما عملت أنا لكم.","13:16":"الحق الحق أقول لكم: ليس عبد أعظم من سيده، ولا رسول أعظم من مرسله.","13:17":"فإن كنتم قد عرفتم هذا، فطوبى لكم إذا عملتم به.","13:18":"وأنا لا أقول هذا عن جميعكم، فأنا أعرف الذين اخترتهم. ولكن لابد أن يتم الكتاب حيث يقول: الآكل من خبزي، رفع علي عقبه!","13:19":"وإني أقول لكم ما سيحدث، قبل حدوثه، حتى متى حدث تؤمنون أني أنا هو.","13:20":"الحق الحق أقول لكم: من يقبل الذي أرسله، يقبلني؛ ومن يقبلني، يقبل الذي أرسلني».","13:21":"ولما قال يسوع هذا اضطربت نفسه وأعلن قائلا: «الحق الحق أقول لكم: إن واحدا منكم سيسلمني!»","13:22":"فتبادل التلاميذ نظرات الحيرة وهم لا يدرون من هو الذي يعنيه.","13:23":"وكان التلميذ الذي يحبه يسوع متكئا على حضنه،","13:24":"فأشار إليه سمعان بطرس أن يسأل يسوع من هو الذي يعنيه.","13:25":"فمال على صدر يسوع وسأله: «من هو ياسيد؟»","13:26":"فأجاب يسوع: «هو الذي أعطيه اللقمة التي أغمسها». ثم غمس اللقمة وأعطاها ليهوذا بن سمعان الإسخريوطي.","13:27":"وبعد اللقمة، دخله الشيطان. فقال له يسوع: «أسرع في ما نويت أن تعمله!»","13:28":"ولم يفهم أحد من المتكئين لماذا قال له ذلك،","13:29":"بل ظن بعضهم أنه يأمره أن يشتري ما يحتاجون إليه في العيد، أو أن يعطي الفقراء بعض المال، لأنه كان أمينا للصندوق.","13:30":"وما إن تناول يهوذا اللقمة، حتى خرج وكان الليل قد أظلم.","13:31":"ولما خرج يهوذا، قال يسوع: «الآن تمجد ابن الإنسان وتمجد الله فيه.","13:32":"وما دام الله قد تمجد فيه، فإنه سيمجده في ذاته، وسريعا سيمجده.","13:33":"ياأولادي الصغار، سأبقى عندكم وقتا قصيرا بعد، ثم تطلبونني، ولكني أقول لكم ما سبق أن قلته لليهود: إنكم لا تقدرون أن تأتوا حيث أنا ذاهب.","13:34":"وصية جديدة أنا أعطيكم: أحبوا بعضكم بعضا، كما أحببتكم أنا، تحبون بعضكم.","13:35":"بهذا يعرف الجميع أنكم تلاميذي: إن كنتم تحبون بعضكم بعضا».","13:36":"فسأله سمعان بطرس: «ياسيد، أين تذهب؟» أجابه يسوع: «لا تقدر أن تتبعني الآن حيث أذهب، ولكنك ستتبعني فيما بعد».","13:37":"فعاد بطرس يسأل: «ياسيد، لماذا لا أقدر أن أتبعك الآن؟ إني أبذل حياتي عوضا عنك!»","13:38":"أجابه يسوع: «أتبذل حياتك عوضا عني؟ الحق الحق أقول لك: لا يصيح الديك حتى تكون قد أنكرتني ثلاث مرات!»","14:1":"«لا تضطرب قلوبكم. أنتم تؤمنون بالله، فآمنوا بي أيضا.","14:2":"في بيت أبي منازل كثيرة، ولو لم يكن الأمر كذلك لقلت لكم! فإني ذاهب لأعد لكم مكانا.","14:3":"وبعدما أذهب وأعد لكم المكان أعود إليكم وآخذكم إلي، لتكونوا حيث أكون أنا.","14:4":"أنتم تعرفون أين أنا ذاهب، وتعرفون الطريق».","14:5":"فقال توما: «ياسيد، لا نعرف أين أنت ذاهب، فكيف نعرف الطريق؟»","14:6":"فأجابه يسوع: «أنا هو الطريق والحق والحياة. لا يأتي أحد إلى الآب إلا بي.","14:7":"إن كنتم قد عرفتموني، فقد عرفتم أبي أيضا، ومنذ الآن تعرفونه وقد رأيتموه».","14:8":"فقال له فيلبس: «ياسيد، أرنا الآب وكفانا!»","14:9":"فأجابه يسوع: «مضت هذه المدة الطويلة وأنا معكم ولم تعرفني يافيلبس؟ الذي رآني رأى الآب، فكيف تقول: أرنا الآب؟","14:10":"ألا تؤمن أني أنا في الآب، وأن الآب في؟ الكلام الذي أقوله لا أقوله من عندي، وإنما الآب الحال في هو يعمل أعماله هذه.","14:11":"صدقوا قولي: إني أنا في الآب وإن الآب في، وإلا فصدقوني بسبب تلك الأعمال.","14:12":"الحق الحق أقول لكم: إن من يؤمن بي يعمل الأعمال التي أنا أعملها، بل يعمل أعظم منها، لأني ذاهب إلى أبي.","14:13":"فأي شيء تطلبونه باسمي أفعله لكم، ليتمجد الآب في الابن.","14:14":"إن طلبتم شيئا باسمي، فإني أفعله.","14:15":"إن كنتم تحبونني فاعملوا بوصاياي.","14:16":"وسوف أطلب من الآب أن يعطيكم معينا آخر يبقى معكم إلى الأبد،","14:17":"وهو روح الحق، الذي لا يقدر العالم أن يتقبله لأنه لا يراه ولا يعرفه، وأما أنتم فتعرفونه لأنه في وسطكم، وسيكون في داخلكم.","14:18":"لن أترككم يتامى، بل سأعود إليكم.","14:19":"بعد قليل لا يراني العالم. أما أنتم فسوف ترونني. ولأني أنا حي، فأنتم أيضا ستحيون.","14:20":"في ذلك اليوم تعلمون أني أنا في أبي، وأنتم في، وأنا فيكم.","14:21":"من كانت عنده وصاياي، ويعمل بها، فذاك يحبني. والذي يحبني، يحبه أبي، وأنا أحبه وأعلن له ذاتي».","14:22":"فسأله يهوذا، غير الإسخريوطي: «ياسيد، ماذا جرى حتى تعلن لنا ذاتك ولا تعلنها للعالم؟»","14:23":"أجابه يسوع: «من يحبني يعمل بكلمتي، ويحبه أبي، وإليه نأتي، وعنده نجعل لنا منزلا.","14:24":"والذي لا يحبني لا يعمل بكلامي. وليس هذا الكلام الذي تسمعونه من عندي، بل من الآب الذي أرسلني،","14:25":"وقد قلت لكم هذه الأمور وأنا مازلت عندكم.","14:26":"وأما الروح القدس، المعين الذي سيرسله الآب باسمي، فإنه يعلمكم كل شيء، ويذكركم بكل ما قلته لكم.","14:27":"سلاما أترك لكم. سلامي أعطيكم. ليس كما يعطي العالم أعطيكم أنا. فلا تضطرب قلوبكم، ولا ترتعب.","14:28":"سمعتم أني قلت لكم: إني ذاهب عنكم ثم أعود إليكم. فلو كنتم تحبونني، لكنتم تبتهجون لأني ذاهب إلى الآب، لأن الآب أعظم مني.","14:29":"ها قد أخبرتكم بالأمر قبل حدوثه، حتى متى حدث تؤمنون.","14:30":"لن أكلمكم كثيرا بعد، فإن سيد هذا العالم قادم علي، ولا شيء له في.","14:31":"إلا أن هذا سيحدث ليعرف العالم أني أحب الآب، وأني مثلما أوصاني الآب هكذا أفعل. قوموا! لنذهب من هنا!","15:1":"«أنا الكرمة الحقيقية، وأبي هو الكرام.","15:2":"كل غصن في لا ينتج ثمرا يقطعه؛ وكل غصن ينتج ثمرا ينقيه لينتج مزيدا من الثمر.","15:3":"أنتم الآن أنقياء بسبب الكلمة التي خاطبتكم بها.","15:4":"فاثبتوا في وأنا فيكم. كما أن الغصن لا يقدر أن ينتج ثمرا إلا إذا ثبت في الكرمة؛ فكذلك أنتم، إلا إذا ثبتم في.","15:5":"أنا الكرمة وأنتم الأغصان. من يثبت في وأنا فيه، فذاك ينتج ثمرا كثيرا. فإنكم بمعزل عني لا تقدرون أن تفعلوا شيئا.","15:6":"إن كان أحد لا يثبت في يطرح خارجا كالغصن فيجف؛ ثم تجمع الأغصان الجافة، وتطرح في النار فتحترق.","15:7":"ولكن، إن ثبتم في، وثبت كلامي فيكم، فاطلبوا ما تريدون يكن لكم.","15:8":"بهذا يتمجد أبي: أن تنتجوا ثمرا كثيرا فتكونون حقا تلاميذي.","15:9":"مثلما أحبني الآب، أحببتكم أنا، فاثبتوا في محبتي.","15:10":"إن عملتم بوصاياي، تثبتون في محبتي، كما عملت أنا بوصايا أبي وأثبت في محبته!","15:11":"قلت لكم هذا ليكون فيكم فرحي، ويكون فرحكم كاملا.","15:12":"وصيتي لكم هي هذه: أن يحب بعضكم بعضا كما أنا أحببتكم.","15:13":"ليس لأحد محبة أعظم من هذه: أن يبذل أحد حياته فدى أحبائه.","15:14":"وأنتم أحبائي إن عملتم بما أوصيكم به.","15:15":"لا أسميكم عبيدا بعد، لأن العبد لا يطلعه سيده على ما يفعله. ولكني قد سميتكم أحباء لأني أطلعتكم على كل ما سمعته من أبي.","15:16":"ليس أنتم اخترتموني، بل أنا اخترتكم وعينتكم لتنطلقوا وتنتجوا ثمرا ويدوم ثمركم، فيعطيكم الآب كل ما تطلبونه باسمي.","15:17":"فبهذا أوصيكم إذن: أن تحبوا بعضكم بعضا.","15:18":"إن أبغضكم العالم، فاعلموا أنه قد أبغضني من قبلكم.","15:19":"لو كنتم من أهل العالم، لكان العالم يحب أهله، ولكن لأنكم لستم من أهل العالم، بل إني اخترتكم من وسط العالم، لذلك يبغضكم العالم.","15:20":"اذكروا الكلمة التي قلتها لكم: ليس عبد أعظم من سيده. فإن كان أهل العالم قد اضطهدوني، فسوف يضطهدونكم؛ وإن كانوا قد عملوا بكلمتي، فسوف يعملون بكلمتكم.","15:21":"ولكنهم سيفعلون هذا كله بكم من أجل اسمي، لأنهم لا يعرفون الذي أرسلني.","15:22":"لو لم آت وأكلمهم، لما كانت لهم خطيئة؛ ولكن لا عذر لهم الآن في خطيئتهم.","15:23":"الذي يبغضني، يبغض أبي أيضا.","15:24":"ولو لم أعمل بينهم أعمالا لم يعملها أحد غيري، لما كانت لهم خطيئة. ولكنهم أبغضوني وأبغضوا أبي، مع أنهم رأوا تلك الأعمال.","15:25":"وقد صار ذلك لتتم الكلمة المكتوبة في شريعتهم: أبغضوني بلا سبب!","15:26":"وعندما يأتي المعين، الذي سأرسله لكم من عند الآب، روح الحق الذي ينبثق من الآب، فهو يشهد لي،","15:27":"وتشهدون لي أنتم أيضا، لأنكم معي من البداية.","16:1":"قلت لكم هذا لكي لا تتزعزعوا.","16:2":"ستطردون خارج المجامع، بل سيأتي وقت يظن فيه من يقتلكم أنه يؤدي خدمة لله.","16:3":"وهم يفعلون هذا بكم لأنهم لم يعرفوا أبي، ولا عرفوني.","16:4":"قلت لكم هذا حتى متى جاء وقت حدوثه تذكرون أنه سبق أن أخبرتكم به. ولم أقل لكم هذا منذ البداية لأني كنت معكم؛","16:5":"أما الآن فإني عائد إلى الذي أرسلني، ولا أحد منكم يسألني: أين تذهب؟","16:6":"عندما أخبرتكم بهذا ملأ الحزن قلوبكم.","16:7":"ولكني أقول لكم الحق: من الأفضل لكم أن أذهب، لأني إن كنت لا أذهب، لا يأتيكم المعين. ولكني إذا ذهبت أرسله إليكم.","16:8":"وعندما يجيء يبكت العالم على الخطيئة وعلى البر وعلى الدينونة:","16:9":"أما على الخطيئة، فلأنهم لا يؤمنون بي،","16:10":"وأما على البر، فلأني عائد إلى الآب فلا ترونني بعد؛","16:11":"وأما على الدينونة، فلأن سيد هذا العالم قد صدر عليه حكم الدينونة.","16:12":"مازال عندي أمور كثيرة أقولها لكم، ولكنكم الآن تعجزون عن احتمالها.","16:13":"ولكن، عندما يأتيكم روح الحق يرشدكم إلى الحق كله، لأنه لا يقول شيئا من عنده، بل يخبركم بما يسمعه، ويطلعكم على ما سوف يحدث.","16:14":"وهو سيمجدني لأن كل ما سيحدثكم به صادر عني.","16:15":"كل ما هو للآب، فهو لي. ولذلك قلت لكم إن ما سيحدثكم به صادر عني.","16:16":"بعد قليل لا ترونني، وبعد ذلك بقليل ترونني!»","16:17":"فتساءل بعض التلاميذ: «ترى، ما معنى قوله: بعد قليل لا ترونني، وبعد ذلك بقليل ترونني، وأيضا: لأني عائد إلى الآب؟»","16:18":"وقالوا: «ما هو هذا القليل الذي يتحدث عنه؟ لسنا نفهم ما يقوله!»","16:19":"وعلم يسوع أنهم يرغبون في أن يسألوه، فقال لهم: «تتساءلون عن معنى قولي: بعد قليل لا ترونني ثم بعد قليل ترونني أيضا.","16:20":"الحق الحق أقول لكم: إنكم ستبكون وتنوحون، أما العالم فيفرح. إنكم ستحزنون، ولكن حزنكم سيتحول إلى فرح.","16:21":"المرأة تحزن إذا حانت ساعتها لتلد. ولكنها حالما تلد طفلها، لا تعود تتذكر عناءها، لفرحها بأن إنسانا قد ولد في العالم.","16:22":"فكذلك أنتم، تحزنون الآن؛ ولكن عندما أعود للقائكم، تبتهج قلوبكم، ولا أحد يسلبكم فرحكم.","16:23":"وفي ذلك اليوم لا تسألونني عن شيء. الحق الحق أقول لكم: إن الآب سيعطيكم كل ما تطلبون منه باسمي.","16:24":"حتى الآن لم تطلبوا باسمي شيئا. اطلبوا تنالوا، فيكون فرحكم كاملا.","16:25":"ضربت لكم أمثالا في كلامي عن هذه الأمور، ولكن سيأتي وقت أحدثكم فيه عن الآب بكلام صريح، دون أمثال.","16:26":"في ذلك اليوم تطلبون من الآب باسمي. ولست أقول لكم إني أطلب إليه عنكم.","16:27":"فإن الآب نفسه يحبكم، لأنكم أحببتموني، وآمنتم بأني من عند الله خرجت.","16:28":"خرجت من عند الآب، وأتيت إلى العالم. وها أنا أترك العالم وأعود إلى الآب».","16:29":"فقال له تلاميذه: «ها أنت الآن تكلمنا كلاما صريحا بغير أمثال.","16:30":"فالآن نعرف أنك تعلم كل شيء، ولا تحتاج إلى أن يسألك أحد. لذلك نؤمن أنك جئت من عند الله».","16:31":"فرد يسوع: «أفالآن تؤمنون؟","16:32":"ستأتي ساعة وها قد حانت الآن فيها تتفرقون كل واحد إلى بيته، وتتركونني وحدي. ولكني لست وحدي، لأن الآب معي.","16:33":"أخبرتكم بهذا كله ليكون لكم في سلام. فإنكم في العالم ستقاسون الضيق. ولكن تشجعوا، فأنا قد انتصرت على العالم!»","17:1":"ولما أنهى يسوع هذا الحديث رفع عينيه نحو السماء، وقال: «أيها الآب، قد حانت الساعة! مجد ابنك، ليمجدك ابنك أيضا،","17:2":"فقد أوليته السلطة على جميع البشر، ليمنح جميع الذين قد وهبتهم له حياة أبدية.","17:3":"والحياة الأبدية هي أن يعرفوك أنت الإله الحق وحدك، والذي أرسلته: يسوع المسيح.","17:4":"أنا مجدتك على الأرض، وأنجزت العمل الذي كلفتني.","17:5":"فمجدني في حضرتك الآن، أيها الآب، بما كان لي من مجد عندك قبل تكوين العالم.","17:6":"أظهرت اسمك للناس الذين وهبتهم لي من العالم. كانوا لك، فوهبتهم لي. وقد عملوا بكلمتك،","17:7":"وعرفوا الآن أن كل ما وهبته لي فهو منك،","17:8":"لأني نقلت إليهم الوصايا التي أوصيتني بها، فقبلوها، وعرفوا حقا أني خرجت من عندك، وآمنوا أنك أنت أرسلتني.","17:9":"من أجل هؤلاء أصلي إليك. لست أصلي الآن من أجل العالم، بل من أجل الذين وهبتهم لي، لأنهم لك.","17:10":"وكل ما هو لي فهو لك، وكل ما هو لك فهو لي؛ وأنا قد تمجدت فيهم.","17:11":"هؤلاء باقون في العالم؛ أما أنا فلست باقيا فيه، لأني عائد إليك. أيها الآب القدوس احفظ في اسمك الذين وهبتهم لي، ليكونوا واحدا، كما نحن واحد.","17:12":"حين كنت معهم، كنت أحفظهم في اسمك. فالذين وهبتهم لي، رعيتهم، ولم يهلك منهم أحد إلا ابن الهلاك، ليتم الكتاب.","17:13":"أما الآن فإني عائد إليك، وأتكلم بهذا وأنا بعد في العالم، ليكون لهم فرحي كاملا فيهم.","17:14":"أبلغتهم كلمتك، فأبغضهم العالم لأنهم ليسوا من العالم.","17:15":"وأنا لا أطلب أن تأخذهم من العالم، بل أن تحفظهم من الشرير.","17:16":"فهم ليسوا من أهل العالم كما أني لست من العالم.","17:17":"قدسهم بالحق؛ إن كلمتك هي الحق.","17:18":"وكما أرسلتني أنت إلى العالم، أرسلتهم أنا أيضا إليه.","17:19":"ومن أجلهم أنا أقدس ذاتي، ليتقدسوا هم أيضا في الحق.","17:20":"ولست أصلي من أجل هؤلاء فقط، بل أيضا من أجل الذين سوف يؤمنون بي بسبب كلمة هؤلاء،","17:21":"ليكون الجميع واحدا؛ أيها الآب، كما أنك أنت في وأنا فيك، ليكونوا هم أيضا واحدا فينا، لكي يؤمن العالم أنك أنت أرسلتني.","17:22":"إني أعطيتهم المجد الذي أعطيتني، ليكونوا واحدا كما نحن واحد.","17:23":"أنا فيهم، وأنت في، ليكتملوا فيصيروا واحدا، حتى يعرف العالم أنك أرسلتني وأنك أحببتهم كما أحببتني.","17:24":"أيها الآب، أريد لهؤلاء الذين وهبتهم لي أن يكونوا معي حيث أكون أنا، فيشاهدوا مجدي الذي أعطيتني، لأنك أحببتني قبل إنشاء العالم.","17:25":"أيها الآب البار، إن العالم لم يعرفك، أما أنا فعرفتك، وهؤلاء عرفوا أنك أنت أرسلتني،","17:26":"وقد عرفتهم اسمك، وسأعرفهم أيضا، لتكون فيهم المحبة التي أحببتني بها، وأكون أنا فيهم».","18:1":"بعدما انتهى يسوع من صلاته هذه، خرج مع تلاميذه وعبروا وادي قدرون. وكان هنالك بستان، فدخله هو وتلاميذه.","18:2":"وكان يهوذا الذي خانه يعرف ذلك المكان لأن يسوع كان يجتمع فيه كثيرا مع تلاميذه.","18:3":"فذهب يهوذا إلى هناك آخذا معه فرقة الجنود وحرس الهيكل، الذين أرسلهم رؤساء الكهنة والفريسيون، وهم يحملون المشاعل والمصابيح والسلاح.","18:4":"وكان يسوع يعرف كل ما سيحدث له، فتقدم نحوهم وقال: «من تريدون؟»","18:5":"فأجابوه: «يسوع الناصري». فقال لهم: «أنا هو». وكان يهوذا الذي خانه واقفا معهم.","18:6":"فلما قال لهم: «أنا هو»، تراجعوا وسقطوا على الأرض!","18:7":"فعاد يسوع يسألهم: «من تريدون؟» أجابوه: «يسوع الناصري».","18:8":"فقال: «قلت لكم: أنا هو، فإن كنتم تريدونني أنا، فدعوا هؤلاء يذهبون».","18:9":"وذلك لتتم الكلمة التي قالها: «إن الذين وهبتهم لي لم يهلك منهم أحد!»","18:10":"وكان مع سمعان بطرس سيف فاستله وضرب به عبد رئيس الكهنة، فقطع أذنه اليمنى. وكان اسم العبد ملخس.","18:11":"فقال يسوع لبطرس: «أعد السيف إلى غمده! الكأس التي أعطاني الآب، ألا أشربها؟»","18:12":"فقبضت الفرقة والقائد وحرس الهيكل على يسوع وقيدوه.","18:13":"وساقوه أولا إلى حنان وهو حمو قيافا رئيس الكهنة في تلك السنة.","18:14":"وقيافا هو الذي أشار على اليهود بأنه من الأفضل أن يموت رجل واحد فدى الأمة.","18:15":"وتبع يسوع سمعان بطرس وتلميذ آخر كان رئيس الكهنة يعرفه. فدخل ذلك التلميذ مع يسوع إلى دار رئيس الكهنة.","18:16":"أما بطرس فوقف بالباب خارجا. فخرج التلميذ الآخر الذي كان رئيس الكهنة يعرفه، وكلم البوابة فأدخل بطرس.","18:17":"فسألت الخادمة البوابة بطرس: «ألست أنت أحد تلاميذ هذا الرجل؟» أجابها: «لا، لست منهم!»","18:18":"وكان الطقس باردا، وقد أوقد العبيد والحراس نارا ووقفوا يستدفئون حولها، فوقف بطرس يستدفئ معهم.","18:19":"وسأل رئيس الكهنة يسوع عن تلاميذه، وعن تعليمه.","18:20":"فأجابه يسوع: «علنا تكلمت إلى العالم، ودائما علمت في المجمع والهيكل حيث يجتمع اليهود كلهم، ولم أقل شيئا في السر.","18:21":"فلماذا تسألني أنا؟ اسأل الذين سمعوا ما تكلمت به إليهم، فهم يعرفون ما قلته!»","18:22":"فلما قال يسوع هذا لطمه أحد الحراس وقال له: «أهكذا تجيب رئيس الكهنة؟»","18:23":"أجابه يسوع: «إن كنت أسأت الكلام فاشهد على الإساءة، أما إذا كنت أحسنت، فلماذا تضربني؟»","18:24":"ثم أرسله حنان مقيدا إلى قيافا رئيس الكهنة.","18:25":"وكان بطرس لايزال واقفا هناك يستدفئ، فسألوه: «ألست أنت أيضا من تلاميذه؟» فأنكر وقال: «لست أنا».","18:26":"فقال واحد من عبيد رئيس الكهنة، وهو نسيب العبد الذي قطع بطرس أذنه: «أما رأيتك معه في البستان؟»","18:27":"فأنكر بطرس مرة أخرى. وفي الحال صاح الديك!","18:28":"ثم أخذوا يسوع من دار قيافا إلى قصر الحاكم الروماني، وكان ذلك في الصباح الباكر. ولم يدخل اليهود إلى القصر لئلا يتنجسوا فلا يتمكنوا من الأكل من خروف الفصح.","18:29":"فخرج بيلاطس إليهم وسألهم: «بماذا تتهمون هذا الرجل؟»","18:30":"أجابوه: «لو لم يكن مذنبا، لما سلمناه إليك!»","18:31":"فقال بيلاطس: «خذوه أنتم وحاكموه حسب شريعتكم». فأجابوه: «لا يحق لنا أن نقتل أحدا!»","18:32":"وقد حدث هذا لتتم الكلمة التي قالها يسوع إشارة إلى الميتة التي سيموتها.","18:33":"فدخل بيلاطس قصره واستدعى يسوع وسأله: «أأنت ملك اليهود؟»","18:34":"فرد يسوع: «أتقول لي هذا من عندك، أم قاله لك عني آخرون؟»","18:35":"فقال بيلاطس: «وهل أنا يهودي؟ إن أمتك ورؤساء الكهنة سلموك إلي. ماذا فعلت؟»","18:36":"أجاب يسوع: «ليست مملكتي من هذا العالم. ولو كانت مملكتي من هذا العالم، لكان حراسي يجاهدون لكي لا أسلم إلى اليهود. أما الآن فمملكتي ليست من هنا».","18:37":"فسأله بيلاطس: «فهل أنت ملك إذن؟» أجابه: «أنت قلت، إني ملك. ولهذا ولدت وجئت إلى العالم: لأشهد للحق، وكل من هو من الحق يصغي لصوتي».","18:38":"فقال له بيلاطس: «ما هو الحق!» ثم خرج إلى اليهود وقال: «إني لا أجد فيه ذنبا!","18:39":"وقد جرت العادة عندكم أن أطلق لكم أحد السجناء في عيد الفصح. فهل تريدون أن أطلق لكم ملك اليهود؟»","18:40":"فصرخوا جميعا قائلين: «لا تطلق هذا، بل باراباس». وكان باراباس لصا!","19:1":"عندئذ أمر بيلاطس بأن يؤخذ يسوع ويجلد.","19:2":"وجدل الجنود إكليلا من الشوك وضعوه على رأسه، وألبسوه رداء أرجوان.","19:3":"وأخذوا يتقدمون إليه ويقولون: «سلام، ياملك اليهود!»، ويلطمونه.","19:4":"وخرج بيلاطس مرة أخرى إلى الجمهور وقال لهم: «سأخرجه إليكم لتروا أني لا أجد فيه ذنبا!»","19:5":"فخرج يسوع وعليه إكليل الشوك ورداء الأرجوان. فقال لهم بيلاطس: «ها هو الإنسان!»","19:6":"فلما رآه رؤساء الكهنة والحرس صرخوا: «اصلبه! اصلبه!» فقال لهم بيلاطس: «بل خذوه أنتم واصلبوه، فإني لا أجد فيه ذنبا!»","19:7":"فأجابه اليهود: «لنا شريعة. وبحسب شريعتنا يتحتم عليه الموت، لأنه جعل نفسه ابن الله».","19:8":"فعندما سمع بيلاطس هذا الكلام، اشتد خوفه،","19:9":"ودخل إلى قصره وسأل يسوع: «من أين أنت؟» فلم يجبه يسوع بشيء.","19:10":"فقال له بيلاطس: «أما تكلمني؟ ألا تعلم أن لي سلطة أن أطلقك، وسلطة أن أصلبك؟»","19:11":"فأجابه يسوع «ما كان لك علي سلطة قط، لو لم تكن قد أعطيت لك من فوق. لذلك فالذي سلمني إليك له خطيئة أعظم...»","19:12":"من أجل ذلك سعى بيلاطس أن يطلقه، ولكن اليهود صرخوا: «إن أطلقت هذا، فلست محبا للقيصر. فإن كل من يجعل نفسه ملكا، يعادي القيصر».","19:13":"فلما سمع بيلاطس هذا الكلام، أمر بإخراج يسوع، وجلس على كرسي القضاء في مكان يسمى «البلاط»، وبالعبرية: «جباثا».","19:14":"وكان الوقت نحو السادسة في يوم الإعداد للفصح. وقال بيلاطس لليهود: «ها هو ملككم!»","19:15":"فصرخوا: «خذه! خذه! اصلبه!» فسألهم بيلاطس: «أأصلب ملككم؟» فأجابه رؤساء الكهنة: «لا ملك لنا إلا القيصر».","19:16":"فسلمه بيلاطس إليهم ليصلب.","19:17":"فخرج وهو حامل صليبه إلى المكان المعروف بمكان الجمجمة، وبالعبرية: «جلجثة»،","19:18":"وهناك صلبوه وصلبوا معه رجلين، واحدا من كل جانب، ويسوع في الوسط.","19:19":"وعلق بيلاطس لافتة على الصليب مكتوبا عليها: «يسوع الناصري ملك اليهود».","19:20":"فقرأ اللافتة كثيرون من اليهود، لأن المكان الذي صلب يسوع فيه كان قريبا من المدينة. وكانت اللافتة مكتوبة بالعبرية واللاتينية واليونانية.","19:21":"فقال رؤساء كهنة اليهود لبيلاطس: «لا تكتب: ملك اليهود، بل إن هذا الإنسان قال: أنا ملك اليهود».","19:22":"فرد بيلاطس: «ما كتبت فقد كتبت!»","19:23":"ولما صلب الجنود يسوع أخذوا ثيابه وقسموها إلى أربعة أقسام، فأخذ كل جندي قسما. وأخذوا القميص أيضا، وكان منسوجا كله من قطعة واحدة، بغير خياطة.","19:24":"فقال الجنود بعضهم لبعض: «لا داعي لتمزيقه، بل لنقترع عليه فنرى من يكسبه!» وقد حدث ذلك ليتم ما جاء في الكتاب: «اقتسموا ثيابي بينهم، وعلى قميصي اقترعوا». وهذا هو ما فعله الجنود.","19:25":"وهناك، عند صليب يسوع، وقفت مريم أمه، وأخت أمه مريم زوجة كلوبا؛ ومريم المجدلية.","19:26":"فلما رأى يسوع أمه، والتلميذ الذي كان يحبه واقفا بالقرب منها، قال لأمه: «أيتها المرأة، هذا ابنك!»","19:27":"ثم قال للتلميذ: «هذه أمك». ومنذ ذلك الحين أخذها التلميذ إلى بيته.","19:28":"بعد هذا رأى يسوع أن كل شيء قد اكتمل، فقال: «أنا عطشان»، ليتم ما جاء في الكتاب.","19:29":"وكان هناك وعاء مليء بالخل، فغمسوا في الخل إسفنجة وضعوها على زوفا، ورفعوها إلى فمه.","19:30":"فلما ذاق يسوع الخل، قال: «قد أكمل!» ثم نكس رأسه وأسلم الروح.","19:31":"ولما كان الإعداد يتم في ذلك اليوم، طلب اليهود من بيلاطس أن تكسر سيقان المصلوبين، فتؤخذ جثثهم لئلا تبقى معلقة على الصليب يوم السبت، ولا سيما لأن ذلك السبت كان يوما عظيما.","19:32":"فجاء الجنود وكسروا ساقي كلا الرجلين المصلوبين مع يسوع.","19:33":"أما يسوع، فلما وصلوا إليه وجدوه قد مات، فلم يكسروا ساقيه.","19:34":"وإنما طعنه أحد الجنود بحربة في جنبه، فخرج في الحال دم وماء.","19:35":"والذي رأى هذا هو يشهد، وشهادته حق وهو يعلم تماما أنه يقول الحق، لكي تؤمنوا أنتم أيضا.","19:36":"وقد حدث هذا ليتم ما جاء في الكتاب: «لن يكسر منه عظم!»","19:37":"وقد جاء أيضا في موضع آخر من الكتاب: «سينظرون إلى ذاك الذي طعنوه».","19:38":"بعد ذلك طلب يوسف الذي من الرامة إلى بيلاطس أن يأذن له بأخذ جثمان يسوع، وكان يوسف هذا تلميذا ليسوع ولكن في السر، لأنه كان خائفا من اليهود، فأذن له بيلاطس. فجاء يوسف وأخذ جثمان يسوع.","19:39":"وجاء أيضا نيقوديموس الذي كان قد أتى من قبل إلى يسوع ليلا، وأحضر معه حوالي ثلاثين لترا من طيب المر المخلوط بالعود.","19:40":"فأخذا جثمان يسوع ولفاه بأكفان مع الطيب، كما كانت عادة اليهود في الدفن.","19:41":"وكان في المكان الذي صلب يسوع فيه بستان، وفي البستان قبر جديد، لم يسبق أن دفن فيه أحد.","19:42":"فدفنا يسوع في ذلك القبر لأنه كان قريبا، ولأن ذلك اليوم كان يوم الإعداد عند اليهود.","20:1":"وفي اليوم الأول من الأسبوع، بكرت مريم المجدلية إلى قبر يسوع، وكان الظلام لايزال مخيما، فرأت الحجر قد رفع عن باب القبر.","20:2":"فأسرعت وجاءت إلى سمعان بطرس والتلميذ الآخر الذي كان يسوع يحبه وقالت لهما: «أخذوا الرب من القبر، ولا ندري أين وضعوه!»","20:3":"فخرج بطرس والتلميذ الآخر وتوجها إلى القبر.","20:4":"وكانا يركضان معا. ولكن التلميذ الآخر سبق بطرس فوصل إلى القبر قبله،","20:5":"وانحنى فرأى الأكفان ملقاة على الأرض، ولكنه لم يدخل.","20:6":"ثم وصل سمعان بطرس في إثره إلى القبر ودخله، فرأى أيضا الأكفان ملقاة على الأرض.","20:7":"والمنديل الذي كان على رأس يسوع وجده ملفوفا وحده في مكان منفصل عن الأكفان.","20:8":"عند ذلك دخل التلميذ الآخر، الذي كان قد وصل إلى القبر أولا، ورأى فآمن.","20:9":"فإن التلاميذ لم يكونوا حتى ذلك الوقت قد فهموا أن الكتاب تنبأ بأنه لابد أن يقوم من بين الأموات.","20:10":"ثم رجع التلميذان إلى بيتهما.","20:11":"أما مريم فظلت واقفة في الخارج تبكي عند القبر. وفيما هي تبكي، انحنت إلى القبر.","20:12":"فرأت ملاكين بثياب بيض، جالسين حيث كان جثمان يسوع موضوعا، واحدا عند الرأس والآخر عند القدمين.","20:13":"فسألاها: «ياامرأة، لماذا تبكين؟» أجابت: «أخذوا سيدي، ولا أدري أين وضعوه».","20:14":"قالت هذا والتفتت إلى الوراء، فرأت يسوع واقفا، ولكنها لم تعلم أنه يسوع.","20:15":"فسألها: «ياامرأة، لماذا تبكين؟ عمن تبحثين؟» فظنت أنه البستاني، فقالت له: «ياسيد، إن كنت أنت قد أخذته فقل لي أين وضعته لآخذه».","20:16":"فناداها يسوع: «يامريم!» فالتفتت وهتفت بالعبرية: «ربوني»، أي: يامعلم.","20:17":"فقال لها: «لا تمسكي بي! فإني لم أصعد بعد إلى الآب، بل اذهبي إلى إخوتي وقولي لهم: إني سأصعد إلى أبي وأبيكم، وإلهي وإلهكم!»","20:18":"فرجعت مريم المجدلية وبشرت التلاميذ قائلة: «إني رأيت الرب!» وأخبرتهم بما قال لها.","20:19":"ولما حل مساء ذلك اليوم، وهو اليوم الأول من الأسبوع، كان التلاميذ مجتمعين في بيت أغلقوا أبوابه خوفا من اليهود، وإذا يسوع يحضر وسطهم قائلا: «سلام لكم!»","20:20":"وإذ قال هذا، أراهم يديه وجنبه، ففرح التلاميذ إذ أبصروا الرب.","20:21":"فقال لهم يسوع: «سلام لكم. كما أن الآب أرسلني، أرسلكم أنا».","20:22":"قال هذا ونفخ فيهم وقال لهم: «اقبلوا الروح القدس.","20:23":"من غفرتم خطاياهم غفرت لهم، ومن أمسكتم خطاياهم، أمسكت!»","20:24":"ولكن توما، أحد التلاميذ الاثني عشر، وهو المعروف بالتوأم، لم يكن مع التلاميذ، حين حضر يسوع.","20:25":"فقال له التلاميذ الآخرون: «إننا رأينا الرب!» فأجاب: «إن كنت لا أرى أثر المسامير في يديه، وأضع إصبعي في مكان المسامير، وأضع يدي في جنبه، فلا أومن!»","20:26":"وبعد ثمانية أيام، إذ كان تلاميذه مجتمعين ثانية داخل البيت وتوما معهم، حضر يسوع والأبواب مغلقة، ووقف في الوسط وقال: «سلام لكم!»","20:27":"ثم قال لتوما: «هات إصبعك إلى هنا، وانظر يدي، وهات يدك وضعها في جنبي. ولا تكن غير مؤمن بل كن مؤمنا!»","20:28":"فهتف توما: «ربي وإلهي».","20:29":"فقال له يسوع: «ألأنك رأيتني آمنت؟ طوبى للذين يؤمنون دون أن يروا»","20:30":"وقد أجرى يسوع أمام تلاميذه آيات أخرى كثيرة لم تدون في الكتاب.","20:31":"وأما هذه الآيات فقد دونت لتؤمنوا بأن يسوع هو المسيح ابن الله، ولكي تكون لكم حياة باسمه إذ تؤمنون.","21:1":"بعد ذلك أظهر يسوع نفسه للتلاميذ مرة أخرى عند شاطئ بحيرة طبرية. وقد أظهر نفسه هكذا:","21:2":"اجتمع سمعان بطرس وتوما، المعروف بالتوأم، ونثنائيل، وهو من قانا بمنطقة الجليل، وابنا زبدي، وتلميذان آخران.","21:3":"فقال لهم سمعان بطرس: «أنا ذاهب للصيد!» فقالوا: «ونحن أيضا نذهب معك». فذهبوا وركبوا القارب، ولكنهم لم يصيدوا شيئا في تلك الليلة.","21:4":"ولما طلع الفجر، وقف يسوع على الشاطئ، ولكن التلاميذ لم يعرفوا أنه يسوع.","21:5":"فسألهم يسوع: «يافتيان، أما عندكم سمك؟» أجابوه: «لا!»","21:6":"فقال لهم: «ألقوا الشبكة إلى يمين القارب، تجدوا!» فألقوها، ولم يعودوا يقدرون أن يجذبوها لكثرة ما فيها من السمك!","21:7":"فقال التلميذ الذي كان يسوع يحبه، لبطرس: «إنه الرب!» وكان بطرس عريانا، فما إن سمع أن ذلك هو الرب، حتى تستر بردائه، وألقى نفسه في الماء سابحا.","21:8":"وجاء باقي التلاميذ بالقارب وهم يجرون شبكة السمك، إذ كانوا غير بعيدين عن الشاطئ إلا نحو مئتي ذراع.","21:9":"فلما نزلوا إلى الشاطئ، رأوا هناك جمرا وسمكا موضوعا عليه، وخبزا.","21:10":"فقال لهم يسوع: «هاتوا من السمك الذي صدتموه الآن!»","21:11":"فصعد سمعان بطرس إلى القارب وجذب الشبكة إلى البر، فإذا فيها مئة وثلاث وخمسون سمكة من السمك الكبير، ومع هذه الكثرة لم تتمزق الشبكة.","21:12":"وقال يسوع للتلاميذ: «تعالوا كلوا». ولم يجرؤ أحد من التلاميذ أن يسأله: من أنت؟ لأنهم عرفوا أنه الرب.","21:13":"ثم تقدم يسوع وأخذ الخبز وناولهم، وكذلك السمك.","21:14":"هذه هي المرة الثالثة التي أظهر فيها يسوع نفسه لتلاميذه بعدما قام من الأموات.","21:15":"وبعدما أكلوا سأل يسوع سمعان بطرس: «ياسمعان بن يونا، أتحبني أكثر مما يحبني هؤلاء؟» فأجابه «نعم يارب، أنت تعلم أني أحبك!» فقال له: «أطعم حملاني!»","21:16":"ثم سأله ثانية: «ياسمعان بن يونا، أتحبني؟» فأجابه: «نعم يارب. أنت تعلم أني أحبك!» قال له: «ارع خرافي»","21:17":"فسأله مرة ثالثة: «ياسمعان بن يونا، أتحبني؟» فحزن بطرس لأن يسوع قال له في المرة الثالثة: «أتحبني». وقال له: «يارب، أنت تعلم كل شيء. أنت تعلم أني أحبك!» فقال له يسوع: «أطعم خرافي!","21:18":"الحق الحق أقول لك: إنك لما كنت شابا كنت تربط حزامك على وسطك وتذهب حيث تريد. ولكن عندما تصير شيخا فإنك تمد يديك، وآخر يربط حزامك ويذهب بك حيث لا تريد!»","21:19":"وقد قال يسوع هذا إشارة إلى الميتة التي سوف يموتها بطرس فيمجد بها الله. ولما قال له ذلك، قال له: «اتبعني».","21:20":"ونظر بطرس وراءه، فرأى التلميذ الذي كان يسوع يحبه يتبعهما، وهو التلميذ الذي مال إلى صدر يسوع في أثناء العشاء وقال له: «ياسيد، من هو الذي سيخونك؟»","21:21":"فلما رآه بطرس سأل يسوع: «يارب وهذا، ماذا يكون له؟»","21:22":"أجابه يسوع: «لو شئت أن يبقى حتى أرجع، فما شأنك؟ اتبعني أنت!»","21:23":"فشاع خبر بين الإخوة أن ذلك التلميذ لن يموت. ولكن يسوع لم يقل لبطرس: «إنه لن يموت!» بل قال: «لو شئت أن يبقى حتى أرجع، فما شأنك؟»","21:24":"هذا التلميذ هو الذي يشهد بهذه الأمور، وقد دونها هنا. ونحن نعلم أن شهادته حق.","21:25":"وهناك أمور أخرى كثيرة عملها يسوع، أظن أنها لو دونت واحدة فواحدة، لما كان العالم كله يسع ما دون من كتب!"};
